            Kind::LessOrEq => "TOKEN_LESS_OR_EQ",
            Kind::More => "TOKEN_MORE",
            Kind::MoreOrEq => "TOKEN_MORE_OR_EQ",
            Kind::AndAnd => "TOKEN_AND_AND",
            Kind::OrOr => "TOKEN_OR_OR",
            Kind::Implication => "TOKEN_IMPLICATION",
            Kind::Update => "TOKEN_UPDATE",
            Kind::Concat => "TOKEN_CONCAT",
