#[derive(Clone, Debug)]
pub struct Token {
    pub kind: Kind,
    pub start: usize,
    pub end: usize,
}

#[derive(Clone, Debug)]
enum Frame {
    Interp { brace_depth: usize },
    StrDq,
    StrIndented,
    Path,
}

pub struct Lexed {
    pub tokens: Vec<Token>,
    pub comments: Vec<Token>,
}

fn is_ident_start(b: u8) -> bool {
    b.is_ascii_alphabetic() || b == b'_'
}
fn is_ident_char(b: u8) -> bool {
    b.is_ascii_alphanumeric() || b == b'_' || b == b'\'' || b == b'-'
}
fn is_path_seg_char(b: u8) -> bool {
    b.is_ascii_alphanumeric() || matches!(b, b'.' | b'_' | b'+' | b'-')
}
fn is_path_char(b: u8) -> bool {
    is_path_seg_char(b) || b == b'/'
}
fn is_uri_body_char(b: u8) -> bool {
    b.is_ascii_alphanumeric()
        || matches!(
            b,
            b'%' | b'/' | b'?' | b':' | b'@' | b'&' | b'=' | b'+' | b'$' | b',' | b'-' | b'_' | b'.'
                | b'!' | b'~' | b'*' | b'\'' | b'#'
        )
}

pub fn tokenize(src: &str) -> Lexed {
    let bytes = src.as_bytes();
    let len = bytes.len();
    let mut pos = 0usize;
    let mut tokens: Vec<Token> = Vec::new();
    let mut frames: Vec<Frame> = Vec::new();

    let mut push = |tokens: &mut Vec<Token>, kind: Kind, start: usize, end: usize| {
        if end > start {
            tokens.push(Token { kind, start, end });
        }
    };
    let char_len = |pos: usize| -> usize {
        if pos >= len {
            0
        } else {
            src[pos..].chars().next().map(|c| c.len_utf8()).unwrap_or(1)
        }
    };

    while pos < len || !frames.is_empty() {
        if pos >= len {
            // Pop any string/path frame; parser will report EOF.
            if frames.pop().is_none() {
                break;
            } else {
                continue;
            }
        }
        match frames.last().cloned() {
            Some(Frame::StrDq) => {
                if frames.last().is_some() {
                    if bytes[pos] == b'"' {
                        push(&mut tokens, Kind::StringEnd, pos, pos + 1);
                        pos += 1;
                        frames.pop();
                        continue;
                    }
                    if src[pos..].starts_with("${") {
                        push(&mut tokens, Kind::InterpolStart, pos, pos + 2);
                        pos += 2;
                        frames.push(Frame::Interp { brace_depth: 0 });
                        continue;
                    }
                    let start = pos;
                    while pos < len {
                        if bytes[pos] == b'"' || src[pos..].starts_with("${") {
                            break;
                        }
                        if bytes[pos] == b'\\' {
                            pos += 1;
                            if pos < len {
                                pos += char_len(pos);
                            }
                        } else if src[pos..].starts_with("$$") {
                            pos += 2;
                        } else {
                            pos += char_len(pos);
                        }
                    }
                    if pos >= len {
                        push(&mut tokens, Kind::Error, start, pos);
                        frames.pop();
                    } else {
                        push(&mut tokens, Kind::StringContent, start, pos);
                    }
                    continue;
                }
            }
            Some(Frame::StrIndented) => {
                // End delimiter if '' not an escape sequence.
                if src[pos..].starts_with("''")
                    && !src[pos..].starts_with("'''")
                    && !src[pos..].starts_with("''$")
                    && !src[pos..].starts_with("''\\")
                {
                    push(&mut tokens, Kind::StringEnd, pos, pos + 2);
                    pos += 2;
                    frames.pop();
                    continue;
                }
                if src[pos..].starts_with("${") {
                    push(&mut tokens, Kind::InterpolStart, pos, pos + 2);
                    pos += 2;
                    frames.push(Frame::Interp { brace_depth: 0 });
                    continue;
                }
                let start = pos;
                while pos < len {
                    if src[pos..].starts_with("''") {
                        if src[pos..].starts_with("'''") {
                            pos += 3;
                            continue;
                        } else if src[pos..].starts_with("''$") {
                            pos += 3;
                            continue;
                        } else if src[pos..].starts_with("''\\") {
                            pos += 3;
                            if pos < len {
                                pos += char_len(pos);
                            }
                            continue;
                        } else {
                            break;
                        }
                    }
                    if src[pos..].starts_with("${") {
                        break;
                    }
                    if src[pos..].starts_with("$$") {
                        pos += 2;
                    } else {
                        pos += char_len(pos);
                    }
                }
                if pos >= len {
                    if pos > start {
                        push(&mut tokens, Kind::Error, start, pos);
                    }
                    frames.pop();
                } else {
                    push(&mut tokens, Kind::StringContent, start, pos);
                }
                continue;
            }
            Some(Frame::Path) => {
                if src[pos..].starts_with("${") {
                    push(&mut tokens, Kind::InterpolStart, pos, pos + 2);
                    pos += 2;
                    frames.push(Frame::Interp { brace_depth: 0 });
                    continue;
                }
                if is_path_char(bytes[pos]) {
                    let start = pos;
                    while pos < len && is_path_char(bytes[pos]) && !src[pos..].starts_with("${") {
                        pos += 1;
                    }
                    push(&mut tokens, Kind::Path, start, pos);
                    continue;
                } else {
                    frames.pop();
                    continue;
                }
            }
            _ => {}
        }

        // Normal mode
        let b = bytes[pos];
        // Whitespace
        if matches!(b, b' ' | b'\t' | b'\n' | b'\r' | 0x0b | 0x0c) {
            let start = pos;
            while pos < len && matches!(bytes[pos], b' ' | b'\t' | b'\n' | b'\r' | 0x0b | 0x0c) {
                pos += 1;
            }
            push(&mut tokens, Kind::Whitespace, start, pos);
            continue;
        }
        if b == b'#' {
            let start = pos;
            while pos < len && bytes[pos] != b'\n' {
                pos += 1;
            }
            push(&mut tokens, Kind::Comment, start, pos);
            continue;
        }
        if src[pos..].starts_with("/*") {
            let start = pos;
            match src[pos + 2..].find("*/") {
                Some(idx) => {
                    pos = pos + 2 + idx + 2;
                    push(&mut tokens, Kind::Comment, start, pos);
                }
                None => {
                    pos = len;
                    push(&mut tokens, Kind::Error, start, pos);
                }
            }
            continue;
        }
        if b == b'"' {
            push(&mut tokens, Kind::StringStart, pos, pos + 1);
            pos += 1;
            frames.push(Frame::StrDq);
            continue;
        }
        if b == b'\'' {
            if src[pos..].starts_with("''") {
                push(&mut tokens, Kind::StringStart, pos, pos + 2);
                pos += 2;
                frames.push(Frame::StrIndented);
            } else {
                push(&mut tokens, Kind::Error, pos, pos + 1);
                pos += 1;
            }
            continue;
        }
        if src[pos..].starts_with("${") {
            push(&mut tokens, Kind::InterpolStart, pos, pos + 2);
            pos += 2;
            frames.push(Frame::Interp { brace_depth: 0 });
            continue;
        }
        if b == b'}' {
            // Close an interpolation if top frame is Interp
            let mut handled = false;
            if let Some(Frame::Interp { brace_depth }) = frames.last_mut() {
                if *brace_depth == 0 {
                    push(&mut tokens, Kind::InterpolEnd, pos, pos + 1);
                    pos += 1;
                    frames.pop();
                    handled = true;
                } else {
                    *brace_depth -= 1;
                    push(&mut tokens, Kind::RBrace, pos, pos + 1);
                    pos += 1;
                    handled = true;
                }
            }
            if handled {
                continue;
            }
            push(&mut tokens, Kind::RBrace, pos, pos + 1);
            pos += 1;
            continue;
        }
        if b == b'{' {
            if let Some(Frame::Interp { brace_depth }) = frames.last_mut() {
                *brace_depth += 1;
            }
            push(&mut tokens, Kind::LBrace, pos, pos + 1);
            pos += 1;
            continue;
        }
        // ~/ path or error
        if b == b'~' {
            if src[pos..].starts_with("~/") {
                let after = pos + 2;
                if after < len
                    && (is_path_seg_char(bytes[after]) || src[after..].starts_with("${"))
                {
                    frames.push(Frame::Path);
                    continue;
                } else {
                    push(&mut tokens, Kind::Error, pos, pos + 2);
                    pos += 2;
                    continue;
                }
            } else {
                push(&mut tokens, Kind::Error, pos, pos + 1);
                pos += 1;
                continue;
            }
        }
        // Numbers
        if b.is_ascii_digit() || (b == b'.' && pos + 1 < len && bytes[pos + 1].is_ascii_digit()) {
            let start = pos;
            let mut is_float = false;
            if b == b'.' {
                is_float = true;
                pos += 1;
                while pos < len && bytes[pos].is_ascii_digit() {
                    pos += 1;
                }
            } else {
                while pos < len && bytes[pos].is_ascii_digit() {
                    pos += 1;
                }
                if pos < len && bytes[pos] == b'.' {
                    // Float if dot followed by digit or not an ident-ish start (1. etc).
                    is_float = true;
                    pos += 1;
                    while pos < len && bytes[pos].is_ascii_digit() {
                        pos += 1;
                    }
                }
            }
            if pos < len && (bytes[pos] == b'e' || bytes[pos] == b'E') {
                let mut q = pos + 1;
                if q < len && (bytes[q] == b'+' || bytes[q] == b'-') {
                    q += 1;
                }
                if q < len && bytes[q].is_ascii_digit() {
                    is_float = true;
                    pos = q;
                    while pos < len && bytes[pos].is_ascii_digit() {
                        pos += 1;
                    }
                }
            }
            push(
                &mut tokens,
                if is_float { Kind::Float } else { Kind::Integer },
                start,
                pos,
            );
            continue;
        }
        // Ident / URI / path starting with ident
        if is_ident_start(b) {
            // URI detection
            if b.is_ascii_alphabetic() {
                let mut j = pos;
                while j < len
                    && (bytes[j].is_ascii_alphanumeric() || matches!(bytes[j], b'+' | b'.' | b'-'))
                {
                    j += 1;
                }
                if j < len && bytes[j] == b':' && j + 1 < len && is_uri_body_char(bytes[j + 1]) {
                    let start = pos;
                    pos = j + 1;
                    while pos < len && is_uri_body_char(bytes[pos]) {
                        pos += 1;
                    }
                    push(&mut tokens, Kind::Uri, start, pos);
                    continue;
                }
            }
            // Path detection: segment then '/'
            {
                let mut j = pos;
                while j < len && is_path_seg_char(bytes[j]) {
                    j += 1;
                }
                if j < len && bytes[j] == b'/' {
                    let after = j + 1;
                    if after < len
                        && (is_path_seg_char(bytes[after]) || src[after..].starts_with("${"))
                    {
                        frames.push(Frame::Path);
                        continue;
                    }
                }
            }
            let start = pos;
            while pos < len && is_ident_char(bytes[pos]) {
                pos += 1;
            }
            let word = &src[start..pos];
            let kind = match word {
                "let" => Kind::Let,
                "in" => Kind::In,
                "if" => Kind::If,
                "then" => Kind::Then,
                "else" => Kind::Else,
                "assert" => Kind::Assert,
                "with" => Kind::With,
                "rec" => Kind::Rec,
                "inherit" => Kind::Inherit,
                "or" => Kind::Or,
                _ => Kind::Ident,
            };
            push(&mut tokens, kind, start, pos);
            continue;
        }
        // Paths starting with /, ./, ../
        if b == b'/' && !src[pos..].starts_with("//") && !src[pos..].starts_with("/*") {
            if pos + 1 < len && is_path_seg_char(bytes[pos + 1]) {
                frames.push(Frame::Path);
                continue;
            }
        }
        if b == b'.' {
            if src[pos..].starts_with("./") || src[pos..].starts_with("../") {
                let after_slash = if src[pos..].starts_with("../") {
                    pos + 3
                } else {
                    pos + 2
                };
                // need a segment char after the final slash of ./ or ../ sequence
                // allow ./foo and ../foo and ../../foo (path scanner will consume)
                let mut p = pos;
                let mut ok = false;
                loop {
                    if src[p..].starts_with("../") {
                        p += 3;
                    } else if src[p..].starts_with("./") {
                        p += 2;
                    } else {
                        break;
                    }
                    if p < len && (is_path_seg_char(bytes[p]) || src[p..].starts_with("${")) {
                        ok = true;
                    }
                }
                let _ = after_slash;
                if ok {
                    frames.push(Frame::Path);
                    continue;
                }
            }
            push(&mut tokens, Kind::Dot, pos, pos + 1);
            pos += 1;
            continue;
        }
        // < env path > / comparison
        if b == b'<' && !src[pos..].starts_with("<=") {
            // try env path: < [path chars /]* >
            let mut j = pos + 1;
            let mut ok = false;
            while j < len {
                if bytes[j] == b'>' {
                    ok = true;
                    break;
                } else if is_path_char(bytes[j]) {
                    j += 1;
                } else {
                    break;
                }
            }
            if ok {
                push(&mut tokens, Kind::Path, pos, j + 1);
                pos = j + 1;
                continue;
            }
        }
        // Multi-char operators
        let multi: &[(&str, Kind)] = &[
            ("...", Kind::Ellipsis),
            ("==", Kind::Equal),
            ("!=", Kind::NotEqual),
            ("<=", Kind::LessOrEq),
            (">=", Kind::MoreOrEq),
            ("&&", Kind::AndAnd),
            ("||", Kind::OrOr),
            ("->", Kind::Implication),
            ("//", Kind::Update),
            ("++", Kind::Concat),
        ];
        let mut matched = false;
        for (txt, kind) in multi {
            if src[pos..].starts_with(txt) {
                push(&mut tokens, *kind, pos, pos + txt.len());
                pos += txt.len();
                matched = true;
                break;
            }
        }
        if matched {
            continue;
        }
        let single = match b {
            b'(' => Some(Kind::LParen),
            b')' => Some(Kind::RParen),
            b'[' => Some(Kind::LBrack),
            b']' => Some(Kind::RBrack),
            b'?' => Some(Kind::Question),
            b',' => Some(Kind::Comma),
            b';' => Some(Kind::Semicolon),
            b':' => Some(Kind::Colon),
            b'@' => Some(Kind::At),
            b'=' => Some(Kind::Assign),
            b'<' => Some(Kind::Less),
            b'>' => Some(Kind::More),
            b'+' => Some(Kind::Add),
            b'-' => Some(Kind::Sub),
            b'*' => Some(Kind::Mul),
            b'/' => Some(Kind::Div),
            b'!' => Some(Kind::Invert),
            _ => None,
        };
        if let Some(kind) = single {
            push(&mut tokens, kind, pos, pos + 1);
            pos += 1;
            continue;
        }
        // Error token: one unicode char
        let l = char_len(pos);
        push(&mut tokens, Kind::Error, pos, pos + l);
        pos += l;
    }

    let comments: Vec<Token> = tokens
        .iter()
        .filter(|t| t.kind == Kind::Comment)
        .cloned()
        .collect();
    let tokens: Vec<Token> = tokens
        .into_iter()
        .filter(|t| t.kind != Kind::Whitespace && t.kind != Kind::Comment)
        .collect();
    Lexed { tokens, comments }
}
