            Some(Frame::StrDq) => {
                if frames.last().is_some() {
                    if bytes[pos] == b'"' {
                        push(&mut tokens, Kind::StringEnd, pos, pos + 1);
                        pos += 1;
                        frames.pop();
                        continue;
                    }
                    if src[pos..].starts_with("${") {
                        push(&mut tokens, Kind::InterpolStart, pos, pos + 2);
                        pos += 2;
                        frames.push(Frame::Interp { brace_depth: 0 });
                        continue;
                    }
                    let start = pos;
                    while pos < len {
                        if bytes[pos] == b'"' || src[pos..].starts_with("${") {
                            break;
                        }
                        if bytes[pos] == b'\\' {
                            pos += 1;
                            if pos < len {
                                pos += char_len(pos);
                            }
                        } else if src[pos..].starts_with("$$") {
                            pos += 2;
                        } else {
                            pos += char_len(pos);
                        }
