                        p += 3;
                    } else if src[p..].starts_with("./") {
                        p += 2;
                    } else {
                        break;
                    }
                    if p < len && (is_path_seg_char(bytes[p]) || src[p..].starts_with("${")) {
                        ok = true;
                    }
                }
                let _ = after_slash;
                if ok {
                    frames.push(Frame::Path);
                    continue;
                }
            }
            push(&mut tokens, Kind::Dot, pos, pos + 1);
            pos += 1;
            continue;
        }
        // < env path > / comparison
        if b == b'<' && !src[pos..].starts_with("<=") {
            // try env path: < [path chars /]* >
            let mut j = pos + 1;
            let mut ok = false;
            while j < len {
                if bytes[j] == b'>' {
                    ok = true;
                    break;
                } else if is_path_char(bytes[j]) {
                    j += 1;
                } else {
                    break;
                }
            }
            if ok {
                push(&mut tokens, Kind::Path, pos, j + 1);
                pos = j + 1;
                continue;
            }
        }
        // Multi-char operators
        let multi: &[(&str, Kind)] = &[
            ("...", Kind::Ellipsis),
            ("==", Kind::Equal),
            ("!=", Kind::NotEqual),
            ("<=", Kind::LessOrEq),
            (">=", Kind::MoreOrEq),
            ("&&", Kind::AndAnd),
            ("||", Kind::OrOr),
            ("->", Kind::Implication),
            ("//", Kind::Update),
            ("++", Kind::Concat),
        ];
        let mut matched = false;
        for (txt, kind) in multi {
            if src[pos..].starts_with(txt) {
                push(&mut tokens, *kind, pos, pos + txt.len());
                pos += txt.len();
                matched = true;
                break;
            }
        }
        if matched {
            continue;
        }
        let single = match b {
            b'(' => Some(Kind::LParen),
            b')' => Some(Kind::RParen),
            b'[' => Some(Kind::LBrack),
            b']' => Some(Kind::RBrack),
            b'?' => Some(Kind::Question),
            b',' => Some(Kind::Comma),
            b';' => Some(Kind::Semicolon),
            b':' => Some(Kind::Colon),
            b'@' => Some(Kind::At),
            b'=' => Some(Kind::Assign),
            b'<' => Some(Kind::Less),
            b'>' => Some(Kind::More),
            b'+' => Some(Kind::Add),
            b'-' => Some(Kind::Sub),
            b'*' => Some(Kind::Mul),
            b'/' => Some(Kind::Div),
            b'!' => Some(Kind::Invert),
            _ => None,
        };
        if let Some(kind) = single {
            push(&mut tokens, kind, pos, pos + 1);
            pos += 1;
            continue;
        }
        // Error token: one unicode char
        let l = char_len(pos);
        push(&mut tokens, Kind::Error, pos, pos + l);
        pos += l;
    }

    let comments: Vec<Token> = tokens
        .iter()
        .filter(|t| t.kind == Kind::Comment)
        .cloned()
        .collect();
    let tokens: Vec<Token> = tokens
        .into_iter()
        .filter(|t| t.kind != Kind::Whitespace && t.kind != Kind::Comment)
        .collect();
    Lexed { tokens, comments }
}
