{"command":"cat > src/parser.rs <<'RS'
use crate::lexer::{tokenize, Kind, Token};

#[derive(Debug, Clone)]
pub enum Attr {
    Ident { name: String, start: usize, end: usize },
    Str { exprs: Vec<Expr> },
    Dynamic { expr: Box<Expr> },
}

#[derive(Debug, Clone)]
pub enum Entry {
    KeyValue {
        attrs: Vec<Attr>,
        value: Expr,
        start: usize,
        end: usize,
    },
    Inherit {
        from: Option<Expr>,
        attrs: Vec<Attr>,
        start: usize,
        end: usize,
    },
}

#[derive(Debug, Clone)]
pub struct PatEntry {
    pub name: String,
    pub start: usize,
    pub end: usize,
    pub default: Option<Expr>,
    pub entry_end: usize,
    pub following_comma: bool,
    pub is_last: bool,
}

#[derive(Debug, Clone)]
pub struct AtBind {
    pub name: String,
    pub start: usize,
    pub end: usize,
    pub at_start: usize,
    pub before_pattern: bool,
}

#[derive(Debug, Clone)]
pub enum LambdaArg {
    Simple { name: String, start: usize, end: usize },
    Pattern {
        entries: Vec<PatEntry>,
        at: Option<AtBind>,
        pattern_start: usize,
        pattern_end: usize,
    },
}

#[derive(Debug, Clone)]
pub struct Expr {
    pub kind: ExprKind,
    pub start: usize,
    pub end: usize,
}

#[derive(Debug, Clone)]
pub enum ExprKind {
    Ident(String),
    Literal,
    Str(Vec<Expr>),
    Path(Vec<Expr>),
    List(Vec<Expr>),
    AttrSet { rec: bool, entries: Vec<Entry> },
    Let { entries: Vec<Entry>, body: Box<Expr>, let_start: usize, body_start: usize },
    Lambda { arg: LambdaArg, body: Box<Expr> },
    Apply(Box<Expr>, Box<Expr>),
    Select { expr: Box<Expr>, attrs: Vec<Attr>, default: Option<Box<Expr>> },
    HasAttr { expr: Box<Expr>, attrs: Vec<Attr> },
    If { cond: Box<Expr>, then: Box<Expr>, else_: Box<Expr> },
    With { expr: Box<Expr>, body: Box<Expr> },
    Assert { expr: Box<Expr>, body: Box<Expr> },
    Unary(Box<Expr>),
    Binary(Box<Expr>, Box<Expr>),
    Dummy,
}

pub struct Parsed {
    pub expr: Expr,
    pub errors: Vec<String>,
    pub comments: Vec<Token>,
}

const VALUE_WANTED: &str = "[TOKEN_L_PAREN, TOKEN_REC, TOKEN_L_BRACE, TOKEN_L_BRACK, TOKEN_STRING_START, TOKEN_IDENT]";

pub struct Parser<'a> {
    src: &'a str,
    toks: Vec<Token>,
    pos: usize,
    errors: Vec<String>,
}

pub fn parse(src: &str) -> Parsed {
    let lexed = tokenize(src);
    let comments = lexed.comments;
    let mut p = Parser {
        src,
        toks: lexed.tokens,
        pos: 0,
        errors: Vec::new(),
    };
    let expr = p.parse_expr();
    if !p.at_eof() {
        let first_start = p.current().map(|t| t.start).unwrap_or(src.len());
        let last_end = p.toks.last().map(|t| t.end).unwrap_or(src.len());
        p.errors
            .push(format!("unexpected token at {}..{}", first_start, last_end));
    }
    Parsed {
        expr,
        errors: p.errors,
        comments,
    }
}

impl<'a> Parser<'a> {
    fn current(&self) -> Option<&Token> {
        self.toks.get(self.pos)
    }
    fn kind(&self) -> Option<Kind> {
        self.current().map(|t| t.kind)
    }
    fn nth_kind(&self, n: usize) -> Option<Kind> {
        self.toks.get(self.pos + n).map(|t| t.kind)
    }
    fn at_eof(&self) -> bool {
        self.pos >= self.toks.len()
    }
    fn bump(&mut self) -> Option<Token> {
        let t = self.toks.get(self.pos).cloned();
        if t.is_some() {
            self.pos += 1;
        }
        t
    }
    fn eat(&mut self, kind: Kind) -> Option<Token> {
        if self.kind() == Some(kind) {
            self.bump()
        } else {
            None
        }
    }
    fn err_unexpected(&mut self, wanted: Option<&str>) {
        match self.current() {
            None => {
                if let Some(w) = wanted {
                    self.errors
                        .push(format!("unexpected end of file, wanted any of {}", w));
                } else {
                    self.errors.push("unexpected end of file".to_string());
                }
            }
            Some(t) => {
                let (name, s, e) = (t.kind.token_name(), t.start, t.end);
                if let Some(w) = wanted {
                    self.errors.push(format!(
                        "unexpected {} at {}..{}, wanted any of {}",
                        name, s, e, w
                    ));
                } else {
                    self.errors
                        .push(format!("unexpected token at {}..{}", s, e));
                }
            }
        }
    }
    fn expect(&mut self, kind: Kind, wanted: Option<&str>) -> Option<Token> {
        if self.kind() == Some(kind) {
            self.bump()
        } else {
            self.err_unexpected(wanted);
            None
        }
    }
    fn expect_no_consume(&mut self, kind: Kind, wanted: Option<&str>) -> bool {
        if self.kind() == Some(kind) {
            self.bump();
            true
        } else {
            self.err_unexpected(wanted);
            false
        }
    }
    fn dummy(&self) -> Expr {
        let p = self.current().map(|t| t.start).unwrap_or(self.src.len());
        Expr {
            kind: ExprKind::Dummy,
            start: p,
            end: p,
        }
    }
    fn text(&self, t: &Token) -> String {
        self.src[t.start..t.end].to_string()
    }

    // Lookahead: is the token stream at pos a lambda pattern starting with { ?
    fn scan_pattern_candidate(&self) -> bool {
        let toks = &self.toks;
        let mut i = self.pos;
        if toks.get(i).map(|t| t.kind) != Some(Kind::LBrace) {
            return false;
        }
        i += 1;
        // empty pattern only if followed by : or @
        match toks.get(i).map(|t| t.kind) {
            Some(Kind::RBrace) => {
                return matches!(
                    toks.get(i + 1).map(|t| t.kind),
                    Some(Kind::Colon) | Some(Kind::At)
                );
            }
            Some(Kind::Ellipsis) => {
                // {...} or {... followed by colon/@
                if toks.get(i + 1).map(|t| t.kind) == Some(Kind::RBrace) {
                    return true;
                } else {
                    return false;
                }
            }
            _ => {}
        }
        loop {
            // entry name
            match toks.get(i).map(|t| t.kind) {
                Some(Kind::Ident) => {
                    i += 1;
                }
                _ => return false,
            }
            // optional default: skip until comma or } at depth 0
            if toks.get(i).map(|t| t.kind) == Some(Kind::Question) {
                i += 1;
                let mut depth = 0i32;
                while let Some(t) = toks.get(i) {
                    match t.kind {
                        Kind::LParen | Kind::LBrace | Kind::LBrack | Kind::InterpolStart => {
                            depth += 1;
                            i += 1;
                        }
                        Kind::RParen | Kind::RBrack | Kind::InterpolEnd => {
                            if depth == 0 {
                                return false;
                            }
                            depth -= 1;
                            i += 1;
                        }
                        Kind::RBrace => {
                            if depth == 0 {
                                break;
                            }
                            depth -= 1;
                            i += 1;
                        }
                        Kind::Comma => {
                            if depth == 0 {
                                break;
                            }
                            i += 1;
                        }
                        _ => {
                            i += 1;
                        }
                    }
                }
            }
            match toks.get(i).map(|t| t.kind) {
                Some(Kind::RBrace) => {
                    return true;
                }
                Some(Kind::Comma) => {
                    i += 1;
                    match toks.get(i).map(|t| t.kind) {
                        Some(Kind::RBrace) => {
                            return true;
                        }
                        Some(Kind::Ellipsis) => {
                            // pattern if } after ellipsis or comma follows (error case)
                            return matches!(
                                toks.get(i + 1).map(|t| t.kind),
                                Some(Kind::RBrace) | Some(Kind::Comma)
                            );
                        }
                        Some(Kind::Ident) => {
                            continue;
                        }
                        _ => return false,
                    }
                }
                _ => return false,
            }
        }
    }

    fn is_lambda_start(&self) -> bool {
        match self.kind() {
            Some(Kind::Ident) => matches!(
                self.nth_kind(1),
                Some(Kind::Colon) | Some(Kind::At)
            ),
            Some(Kind::LBrace) => self.scan_pattern_candidate(),
            _ => false,
        }
    }

    pub fn parse_expr(&mut self) -> Expr {
        match self.kind() {
            Some(Kind::Let) => self.parse_let(),
            Some(Kind::If) => {
                let start_tok = self.bump().unwrap();
                let cond = self.parse_expr();
                self.expect(Kind::Then, Some("[TOKEN_THEN]"));
                let then = self.parse_expr();
                self.expect(Kind::Else, Some("[TOKEN_ELSE]"));
                let else_ = self.parse_expr();
                let end = else_.end;
                Expr {
                    kind: ExprKind::If {
                        cond: Box::new(cond),
                        then: Box::new(then),
                        else_: Box::new(else_),
                    },
                    start: start_tok.start,
                    end,
                }
            }
            Some(Kind::Assert) => {
                let start_tok = self.bump().unwrap();
                let cond = self.parse_expr();
                self.expect(Kind::Semicolon, Some("[TOKEN_SEMICOLON]"));
                let body = self.parse_expr();
                let end = body.end;
                Expr {
                    kind: ExprKind::Assert {
                        expr: Box::new(cond),
                        body: Box::new(body),
                    },
                    start: start_tok.start,
                    end,
                }
            }
            Some(Kind::With) => {
                let start_tok = self.bump().unwrap();
                let e = self.parse_expr();
                self.expect(Kind::Semicolon, Some("[TOKEN_SEMICOLON]"));
                let body = self.parse_expr();
                let end = body.end;
                Expr {
                    kind: ExprKind::With {
                        expr: Box::new(e),
                        body: Box::new(body),
                    },
                    start: start_tok.start,
                    end,
                }
            }
            Some(Kind::Invert) => {
                let start_tok = self.bump().unwrap();
                let e = self.parse_expr();
                let end = e.end;
                Expr {
                    kind: ExprKind::Unary(Box::new(e)),
                    start: start_tok.start,
                    end,
                }
            }
            _ => {
                if self.is_lambda_start() {
                    self.parse_lambda()
                } else {
                    self.parse_binary(0)
                }
            }
        }
    }

    fn parse_let(&mut self) -> Expr {
        let let_tok = self.bump().unwrap(); // let
        let mut entries = Vec::new();
        let body;
        loop {
            match self.kind() {
                Some(Kind::In) => {
                    self.bump();
                    body = self.parse_expr();
                    break;
                }
                None => {
                    self.errors.push("unexpected end of file".to_string());
                    body = self.parse_expr();
                    break;
                }
                Some(Kind::Inherit) => {
                    entries.push(self.parse_inherit());
                }
                _ => {
                    entries.push(self.parse_assignment());
                }
            }
        }
        let end = body.end;
        Expr {
            kind: ExprKind::Let {
                let_start: let_tok.start,
                body_start: body.start,
                entries,
                body: Box::new(body),
            },
            start: let_tok.start,
            end,
        }
    }

    fn parse_inherit(&mut self) -> Entry {
        let start_tok = self.bump().unwrap(); // inherit
        let mut from = None;
        if self.kind() == Some(Kind::LParen) {
            self.bump();
            let e = self.parse_expr();
            self.expect(Kind::RParen, Some("[TOKEN_R_PAREN]"));
            from = Some(e);
        }
        let mut attrs = Vec::new();
        loop {
            match self.kind() {
                Some(Kind::Ident)
                | Some(Kind::Or)
                | Some(Kind::StringStart)
                | Some(Kind::InterpolStart) => {
                    attrs.push(self.parse_attr());
                }
                _ => break,
            }
        }
        let semi = self.expect(Kind::Semicolon, Some("[TOKEN_SEMICOLON]"));
        let end = semi.map(|t| t.end).unwrap_or_else(|| {
            attrs
                .last()
                .map(|a| match a {
                    Attr::Ident { end, .. } => *end,
                    _ => start_tok.end,
                })
                .unwrap_or(start_tok.end)
        });
        Entry::Inherit {
            from,
            attrs,
            start: start_tok.start,
            end,
        }
    }

    fn parse_attr(&mut self) -> Attr {
        match self.kind() {
            Some(Kind::Ident) | Some(Kind::Or) => {
                let t = self.bump().unwrap();
                Attr::Ident {
                    name: self.text(&t),
                    start: t.start,
                    end: t.end,
                }
            }
            Some(Kind::StringStart) => {
                let s = self.parse_string();
                match s.kind {
                    ExprKind::Str(exprs) => Attr::Str { exprs },
                    _ => Attr::Str { exprs: vec![] },
                }
            }
            Some(Kind::InterpolStart) => {
                self.bump();
                let e = self.parse_expr();
                self.expect(Kind::InterpolEnd, Some("[TOKEN_INTERPOL_END]"));
                Attr::Dynamic {
                    expr: Box::new(e),
                }
            }
            _ => {
                self.err_unexpected(Some("[TOKEN_IDENT, TOKEN_OR]"));
                if !self.at_eof() {
                    let t = self.bump().unwrap();
                    Attr::Ident {
                        name: String::new(),
                        start: t.start,
                        end: t.end,
                    }
                } else {
                    Attr::Ident {
                        name: String::new(),
                        start: self.src.len(),
                        end: self.src.len(),
                    }
                }
            }
        }
    }

    fn parse_attr_path(&mut self) -> Vec<Attr> {
        let mut attrs = vec![self.parse_attr()];
        while self.kind() == Some(Kind::Dot) {
            self.bump();
            attrs.push(self.parse_attr());
        }
        attrs
    }

    fn parse_assignment(&mut self) -> Entry {
        let start = self.current().map(|t| t.start).unwrap_or(self.src.len());
        let attrs = self.parse_attr_path();
        self.expect(Kind::Assign, Some("[TOKEN_ASSIGN]"));
        let value = self.parse_expr();
        let semi = self.expect(Kind::Semicolon, Some("[TOKEN_SEMICOLON]"));
        let end = semi.map(|t| t.end).unwrap_or(value.end);
        Entry::KeyValue {
            attrs,
            value,
            start,
            end,
        }
    }

    fn parse_attrset(&mut self, rec: bool) -> Expr {
        // current must be {
        let start_tok = match self.bump() {
            Some(t) => t,
            None => {
                self.errors.push("unexpected end of file".to_string());
                return self.dummy();
            }
        };
        let mut entries = Vec::new();
        loop {
            match self.kind() {
                Some(Kind::RBrace) => {
                    let t = self.bump().unwrap();
                    return Expr {
                        kind: ExprKind::AttrSet { rec, entries },
                        start: start_tok.start,
                        end: t.end,
                    };
                }
                None => {
                    self.errors.push("unexpected end of file".to_string());
                    return Expr {
                        kind: ExprKind::AttrSet { rec, entries },
                        start: start_tok.start,
                        end: self.src.len(),
                    };
                }
                Some(Kind::Inherit) => {
                    entries.push(self.parse_inherit());
                }
                _ => {
                    entries.push(self.parse_assignment());
                }
            }
        }
    }

    fn parse_string(&mut self) -> Expr {
        let start_tok = self.bump().unwrap(); // STRING_START
        let mut exprs = Vec::new();
        loop {
            match self.kind() {
                Some(Kind::StringContent) => {
                    self.bump();
                }
                Some(Kind::InterpolStart) => {
                    self.bump();
                    let e = self.parse_expr();
                    exprs.push(e);
                    self.expect(Kind::InterpolEnd, Some("[TOKEN_INTERPOL_END]"));
                }
                Some(Kind::StringEnd) => {
                    let t = self.bump().unwrap();
                    return Expr {
                        kind: ExprKind::Str(exprs),
                        start: start_tok.start,
                        end: t.end,
                    };
                }
                None => {
                    self.errors.push(
                        "unexpected end of file, wanted any of [TOKEN_STRING_END, TOKEN_STRING_CONTENT, TOKEN_INTERPOL_START]"
                            .to_string(),
                    );
                    self.errors.push(
                        "unexpected end of file, wanted any of [TOKEN_STRING_END]".to_string(),
                    );
                    return Expr {
                        kind: ExprKind::Str(exprs),
                        start: start_tok.start,
                        end: self.src.len(),
                    };
                }
                _ => {
                    self.err_unexpected(Some(
                        "[TOKEN_STRING_END, TOKEN_STRING_CONTENT, TOKEN_INTERPOL_START]",
                    ));
                    if !self.at_eof() {
                        self.bump();
                    }
                    if self.at_eof() {
                        self.errors.push("unexpected end of file, wanted any of [TOKEN_STRING_END, TOKEN_STRING_CONTENT, TOKEN_INTERPOL_START]".to_string());
                        self.errors.push(
                            "unexpected end of file, wanted any of [TOKEN_STRING_END]"
                                .to_string(),
                        );
                        return Expr {
                            kind: ExprKind::Str(exprs),
                            start: start_tok.start,
                            end: self.src.len(),
                        };
                    }
                }
            }
        }
    }

    fn parse_pattern(&mut self) -> (Vec<PatEntry>, Option<AtBind>, usize, usize, bool) {
        // may be called when current is {, or after ident@ expecting {
        let lbrace = self.expect(Kind::LBrace, Some("[TOKEN_L_BRACE]"));
        let pattern_start = lbrace
            .as_ref()
            .map(|t| t.start)
            .unwrap_or_else(|| self.current().map(|t| t.start).unwrap_or(self.src.len()));
        let mut entries: Vec<PatEntry> = Vec::new();
        let mut pattern_end = pattern_start;
        loop {
            match self.kind() {
                Some(Kind::RBrace) => {
                    let t = self.bump().unwrap();
                    pattern_end = t.end;
                    break;
                }
                None => {
                    self.err_unexpected(Some("[TOKEN_R_BRACE, TOKEN_ELLIPSIS, TOKEN_IDENT]"));
                    pattern_end = self.src.len();
                    break;
                }
                Some(Kind::Ellipsis) => {
                    self.bump();
                    // after ellipsis expect }
                    if self.kind() == Some(Kind::RBrace) {
                        let t = self.bump().unwrap();
                        pattern_end = t.end;
                    } else {
                        self.expect(Kind::RBrace, Some("[TOKEN_R_BRACE]"));
                        pattern_end = entries.last().map(|e| e.entry_end).unwrap_or(pattern_start);
                    }
                    break;
                }
                Some(Kind::Ident) => {
                    let t = self.bump().unwrap();
                    let name = self.text(&t);
                    let (default, entry_end) = if self.kind() == Some(Kind::Question) {
                        self.bump();
                        let d = self.parse_expr();
                        let eend = d.end;
                        (Some(d), eend)
                    } else {
                        (None, t.end)
                    };
                    let mut following_comma = false;
                    if self.kind() == Some(Kind::Comma) {
                        self.bump();
                        following_comma = true;
                    }
                    entries.push(PatEntry {
                        name,
                        start: t.start,
                        end: t.end,
                        default,
                        entry_end,
                        following_comma,
                        is_last: false,
                    });
                }
                _ => {
                    self.err_unexpected(Some("[TOKEN_R_BRACE, TOKEN_ELLIPSIS, TOKEN_IDENT]"));
                    if !self.at_eof() {
                        self.bump();
                    }
                }
            }
        }
        let n = entries.len();
        for (idx, e) in entries.iter_mut().enumerate() {
            e.is_last = idx + 1 == n;
        }
        (entries, None, pattern_start, pattern_end, false)
    }

    fn parse_lambda(&mut self) -> Expr {
        let start_pos = self.current().map(|t| t.start).unwrap_or(self.src.len());
        // ident @ pattern
        if self.kind() == Some(Kind::Ident) && self.nth_kind(1) == Some(Kind::At) {
            let name_tok = self.bump().unwrap();
            let at_tok = self.bump().unwrap();
            let (entries, _, pstart, pend, _) = self.parse_pattern();
            let at = AtBind {
                name: self.text(&name_tok),
                start: name_tok.start,
                end: name_tok.end,
                at_start: at_tok.start,
                before_pattern: true,
            };
            self.expect(Kind::Colon, Some("[TOKEN_COLON]"));
            let body = self.parse_expr();
            let end = body.end;
            return Expr {
                kind: ExprKind::Lambda {
                    arg: LambdaArg::Pattern {
                        entries,
                        at: Some(at),
                        pattern_start: pstart,
                        pattern_end: pend,
                    },
                    body: Box::new(body),
                },
                start: start_pos,
                end,
            };
        }
        // simple ident:
        if self.kind() == Some(Kind::Ident) && self.nth_kind(1) == Some(Kind::Colon) {
            let name_tok = self.bump().unwrap();
            self.bump(); // colon
            let name = self.text(&name_tok);
            let body = self.parse_expr();
            let end = body.end;
            return Expr {
                kind: ExprKind::Lambda {
                    arg: LambdaArg::Simple {
                        name,
                        start: name_tok.start,
                        end: name_tok.end,
                    },
                    body: Box::new(body),
                },
                start: start_pos,
                end,
            };
        }
        // pattern
        let (entries, _, pstart, pend, _) = self.parse_pattern();
        let mut at = None;
        if self.kind() == Some(Kind::At) {
            let at_tok = self.bump().unwrap();
            match self.kind() {
                Some(Kind::Ident) => {
                    let name_tok = self.bump().unwrap();
                    at = Some(AtBind {
                        name: self.text(&name_tok),
                        start: name_tok.start,
                        end: name_tok.end,
                        at_start: at_tok.start,
                        before_pattern: false,
                    });
                }
                _ => {
                    self.err_unexpected(Some("[TOKEN_IDENT]"));
                }
            }
        }
        self.expect(Kind::Colon, Some("[TOKEN_COLON]"));
        let body = self.parse_expr();
        let end = body.end;
        Expr {
            kind: ExprKind::Lambda {
                arg: LambdaArg::Pattern {
                    entries,
                    at,
                    pattern_start: pstart,
                    pattern_end: pend,
                },
                body: Box::new(body),
            },
            start: start_pos,
            end,
        }
    }

    fn parse_list(&mut self) -> Expr {
        let start_tok = self.bump().unwrap(); // [
        let mut items = Vec::new();
        loop {
            match self.kind() {
                Some(Kind::RBrack) => {
                    let t = self.bump().unwrap();
                    return Expr {
                        kind: ExprKind::List(items),
                        start: start_tok.start,
                        end: t.end,
                    };
                }
                None => {
                    self.errors.push("unexpected end of file".to_string());
                    return Expr {
                        kind: ExprKind::List(items),
                        start: start_tok.start,
                        end: self.src.len(),
                    };
                }
                _ => {
                    let item = self.parse_list_element();
                    items.push(item);
                }
            }
        }
    }

    fn parse_list_element(&mut self) -> Expr {
        // Lambda or value with selects
        if self.is_lambda_start() {
            return self.parse_lambda();
        }
        self.parse_select()
    }

    fn parse_value(&mut self) -> Expr {
        match self.kind() {
            Some(Kind::LParen) => {
                let s = self.bump().unwrap();
                let e = self.parse_expr();
                let endtok = self.expect(Kind::RParen, None);
                let end = endtok.map(|t| t.end).unwrap_or(e.end);
                Expr {
                    kind: e.kind,
                    start: s.start,
                    end,
                }
            }
            Some(Kind::LBrack) => self.parse_list(),
            Some(Kind::LBrace) => self.parse_attrset(false),
            Some(Kind::Rec) => {
                let rec_tok = self.bump().unwrap();
                if self.kind() == Some(Kind::LBrace) {
                    let mut e = self.parse_attrset(true);
                    e.start = rec_tok.start;
                    e
                } else {
                    self.err_unexpected(Some("[TOKEN_L_BRACE]"));
                    if !self.at_eof() {
                        self.bump();
                    }
                    self.err_unexpected(Some("[TOKEN_L_BRACE]"));
                    self.dummy()
                }
            }
            Some(Kind::StringStart) => self.parse_string(),
            Some(Kind::Ident) => {
                let t = self.bump().unwrap();
                Expr {
                    kind: ExprKind::Ident(self.text(&t)),
                    start: t.start,
                    end: t.end,
                }
            }
            Some(Kind::Integer) | Some(Kind::Float) | Some(Kind::Uri) => {
                let t = self.bump().unwrap();
                Expr {
                    kind: ExprKind::Literal,
                    start: t.start,
                    end: t.end,
                }
            }
            Some(Kind::Path) => {
                let t = self.bump().unwrap();
                let mut exprs = Vec::new();
                let mut end = t.end;
                // path interpolations
                loop {
                    if self.kind() == Some(Kind::InterpolStart) {
                        self.bump();
                        let e = self.parse_expr();
                        end = e.end;
                        exprs.push(e);
                        if let Some(tok) = self.expect(Kind::InterpolEnd, Some("[TOKEN_INTERPOL_END]")) {
                            end = tok.end;
                        }
                        if self.kind() == Some(Kind::Path) {
                            let pt = self.bump().unwrap();
                            end = pt.end;
                            continue;
                        }
                    }
                    break;
                }
                Expr {
                    kind: ExprKind::Path(exprs),
                    start: t.start,
                    end,
                }
            }
            _ => {
                self.err_unexpected(Some(VALUE_WANTED));
                if !self.at_eof() {
                    self.bump();
                }
                self.dummy()
            }
        }
    }

    fn parse_value_or_lambda(&mut self) -> Expr {
        if self.is_lambda_start() {
            self.parse_lambda()
        } else {
            self.parse_value()
        }
    }

    fn parse_select(&mut self) -> Expr {
        let mut base = self.parse_value_or_lambda();
        loop {
            if self.kind() == Some(Kind::Dot) {
                self.bump();
                let attrs = self.parse_attr_path();
                let mut default = None;
                let mut end = base.end;
                if self.kind() == Some(Kind::Or) {
                    self.bump();
                    let d = self.parse_application();
                    end = d.end;
                    default = Some(Box::new(d));
                }
                let start = base.start;
                base = Expr {
                    kind: ExprKind::Select {
                        expr: Box::new(base),
                        attrs,
                        default,
                    },
                    start,
                    end,
                };
            } else if self.kind() == Some(Kind::Or) {
                // a or b form
                self.bump();
                let d = self.parse_application();
                let start = base.start;
                let end = d.end;
                base = Expr {
                    kind: ExprKind::Select {
                        expr: Box::new(base),
                        attrs: Vec::new(),
                        default: Some(Box::new(d)),
                    },
                    start,
                    end,
                };
            } else {
                break;
            }
        }
        base
    }

    fn can_start_argument(&self) -> bool {
        matches!(
            self.kind(),
            Some(Kind::LParen)
                | Some(Kind::Rec)
                | Some(Kind::LBrace)
                | Some(Kind::LBrack)
                | Some(Kind::StringStart)
                | Some(Kind::Ident)
                | Some(Kind::Integer)
                | Some(Kind::Float)
                | Some(Kind::Path)
                | Some(Kind::Uri)
                | Some(Kind::Sub)
        )
    }

    fn parse_argument(&mut self) -> Expr {
        if self.kind() == Some(Kind::Sub) {
            let s = self.bump().unwrap();
            let e = self.parse_select();
            let end = e.end;
            return Expr {
                kind: ExprKind::Unary(Box::new(e)),
                start: s.start,
                end,
            };
        }
        self.parse_select()
    }

    fn parse_application(&mut self) -> Expr {
        let mut left = if self.kind() == Some(Kind::Sub) {
            let s = self.bump().unwrap();
            let e = self.parse_select();
            let end = e.end;
            Expr {
                kind: ExprKind::Unary(Box::new(e)),
                start: s.start,
                end,
            }
        } else {
            self.parse_select()
        };
        while self.can_start_argument() {
            let arg = self.parse_argument();
            let start = left.start;
            let end = arg.end;
            left = Expr {
                kind: ExprKind::Apply(Box::new(left), Box::new(arg)),
                start,
                end,
            };
        }
        left
    }

    fn parse_binary(&mut self, level: usize) -> Expr {
        // levels: 0 -> implication, 1 ||, 2 &&, 3 eq, 4 cmp, 5 //, 6 ++, 7 +-, 8 */, 9 hasattr/application
        if level >= 9 {
            // has-attr postfix over application
            let mut e = self.parse_application();
            while self.kind() == Some(Kind::Question) {
                self.bump();
                let attrs = self.parse_attr_path();
                let start = e.start;
                let end = attrs
                    .last()
                    .map(|a| match a {
                        Attr::Ident { end, .. } => *end,
                        _ => e.end,
                    })
                    .unwrap_or(e.end);
                e = Expr {
                    kind: ExprKind::HasAttr {
                        expr: Box::new(e),
                        attrs,
                    },
                    start,
                    end,
                };
            }
            return e;
        }
        let ops: &[Kind] = match level {
            0 => &[Kind::Implication],
            1 => &[Kind::OrOr],
            2 => &[Kind::AndAnd],
            3 => &[Kind::Equal, Kind::NotEqual],
            4 => &[Kind::Less, Kind::LessOrEq, Kind::More, Kind::MoreOrEq],
            5 => &[Kind::Update],
            6 => &[Kind::Concat],
            7 => &[Kind::Add, Kind::Sub],
            8 => &[Kind::Mul, Kind::Div],
            _ => unreachable!(),
        };
        let right_assoc = matches!(level, 0 | 5 | 6);
        let mut left = self.parse_binary(level + 1);
        loop {
            let k = match self.kind() {
                Some(k) if ops.contains(&k) => k,
                _ => break,
            };
            let _ = k;
            self.bump();
            let right = if right_assoc {
                self.parse_binary(level)
            } else {
                self.parse_binary(level + 1)
            };
            let start = left.start;
            let end = right.end;
            left = Expr {
                kind: ExprKind::Binary(Box::new(left), Box::new(right)),
                start,
                end,
            };
            if !right_assoc {
                continue;
            }
        }
        left
    }
}
