use crate::lexer::Token;
use crate::parser::{Attr, AtBind, Entry, Expr, ExprKind, LambdaArg, PatEntry};
use std::collections::{HashMap, HashSet};

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum BindingKind {
    Let,
    LambdaArg,
    PatternEntry,
    PatternAt,
    Rec,
}

impl BindingKind {
    pub fn label(self) -> &'static str {
        match self {
            BindingKind::Let => "let binding",
            BindingKind::LambdaArg => "lambda argument",
            BindingKind::PatternEntry | BindingKind::PatternAt => "lambda pattern",
            BindingKind::Rec => "let binding",
        }
    }
    pub fn color_code(self) -> u32 {
        match self {
            BindingKind::Let | BindingKind::Rec => 31,
            BindingKind::PatternEntry | BindingKind::PatternAt => 35,
            BindingKind::LambdaArg => 36,
        }
    }
}

#[derive(Clone, Debug)]
pub enum EditInfo {
    LetAssignment {
        entry_start: usize,
        entry_end: usize,
    },
    LetInherit {
        stmt_start: usize,
        stmt_end: usize,
        stmt_id: usize,
    },
    PatternEntry {
        entry_start: usize,
        entry_end: usize,
        following_comma: bool,
        is_last: bool,
    },
    PatternAt {
        pattern_start: usize,
        pattern_end: usize,
        at_start: usize,
        before_pattern: bool,
    },
    LambdaArg,
    None,
}

#[derive(Clone, Debug)]
pub struct Binding {
    pub id: usize,
    pub name: String,
    pub start: usize,
    pub end: usize,
    pub kind: BindingKind,
    pub scope: usize,
    pub skipped: bool,
    pub root_used: bool,
    pub users: HashSet<usize>,
    pub edit: EditInfo,
}

#[derive(Clone, Debug)]
pub struct LetEntryInfo {
    pub fully_removable_bindings: Vec<usize>, // binding ids if this entry can be removed when all are results; empty if not removable
    pub has_non_removable: bool,
    pub entry_start: usize,
    pub entry_end: usize,
    pub is_inherit_stmt: bool,
    pub stmt_id: usize,
}

#[derive(Clone, Debug)]
pub struct LetInfo {
    pub let_start: usize,
    pub body_start: usize,
    pub entries: Vec<LetEntryInfo>,
    pub scope: usize,
}

#[derive(Clone, Debug)]
pub struct Scope {
    pub id: usize,
    pub bindings: Vec<usize>,
    #[allow(dead_code)]
    pub kind: ScopeKind,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum ScopeKind {
    Let,
    Pattern,
    Simple,
    Rec,
}

pub struct Analyzer<'a> {
    pub src: &'a str,
    pub bindings: Vec<Binding>,
    pub scopes: Vec<Scope>,
    pub lets: Vec<LetInfo>,
    comments: Vec<(usize, usize)>, // start,end byte of comments
    env: Vec<usize>,
    owners: Vec<(usize, usize)>, // (scope, binding)
    next_stmt_id: usize,
}

#[derive(Clone)]
pub struct Options {
    pub no_lambda_arg: bool,
    pub no_lambda_pattern_names: bool,
    pub no_underscore: bool,
    pub warn_used_underscore: bool,
}

#[derive(Clone, Debug)]
pub struct ResultBinding {
    pub name: String,
    pub start: usize,
    pub end: usize,
    pub kind: BindingKind,
    pub message: String,
    pub binding_id: usize,
}

impl<'a> Analyzer<'a> {
    pub fn new(src: &'a str, comments: &[Token]) -> Self {
        Analyzer {
            src,
            bindings: Vec::new(),
            scopes: Vec::new(),
            lets: Vec::new(),
            comments: comments.iter().map(|t| (t.start, t.end)).collect(),
            env: Vec::new(),
            owners: Vec::new(),
            next_stmt_id: 0,
        }
    }

    fn is_skipped(&self, name_start: usize) -> bool {
        // line of name_start (1-based)
        let line_of = |pos: usize| -> usize {
            self.src[..pos].bytes().filter(|&b| b == b'\n').count() + 1
        };
        let bline = line_of(name_start);
        for (cs, ce) in &self.comments {
            let text = &self.src[*cs..*ce];
            if !text.contains("deadnix: skip") {
                continue;
            }
            if name_start <= *ce {
                continue;
            }
            let cline_end = line_of(*ce);
            if bline == cline_end || bline == cline_end + 1 {
                return true;
            }
        }
        false
    }

    fn new_scope(&mut self, kind: ScopeKind) -> usize {
        let id = self.scopes.len();
        self.scopes.push(Scope {
            id,
            bindings: Vec::new(),
            kind,
        });
        id
    }

    fn add_binding(
        &mut self,
        name: String,
        start: usize,
        end: usize,
        kind: BindingKind,
        scope: usize,
        edit: EditInfo,
    ) -> usize {
        let id = self.bindings.len();
        let skipped = self.is_skipped(start);
        self.bindings.push(Binding {
            id,
            name,
            start,
            end,
            kind,
            scope,
            skipped,
            root_used: false,
            users: HashSet::new(),
            edit,
        });
        self.scopes[scope].bindings.push(id);
        id
    }

    fn resolve_in_env(&self, env: &[usize], name: &str) -> Option<(usize, Vec<usize>)> {
        for scope_id in env.iter().rev() {
            let ids: Vec<usize> = self.scopes[*scope_id]
                .bindings
                .iter()
                .cloned()
                .filter(|bid| self.bindings[*bid].name == name)
                .collect();
            if !ids.is_empty() {
                return Some((*scope_id, ids));
            }
        }
        None
    }

    fn mark_usage_env(&mut self, env: &[usize], name: &str) {
        if let Some((_scope, ids)) = self.resolve_in_env(env, name) {
            self.mark_ids(&ids);
        }
    }

    fn mark_ids(&mut self, ids: &[usize]) {
        for &tid in ids {
            let tscope = self.bindings[tid].scope;
            let owners_for_scope: Vec<usize> = self
                .owners
                .iter()
                .filter(|(s, _)| *s == tscope)
                .map(|(_, b)| *b)
                .collect();
            if owners_for_scope.is_empty() {
                self.bindings[tid].root_used = true;
            } else {
                for owner in owners_for_scope {
                    if owner != tid {
                        self.bindings[tid].users.insert(owner);
                    }
                }
            }
        }
    }

    fn mark_usage(&mut self, name: &str) {
        let env = self.env.clone();
        self.mark_usage_env(&env, name);
    }

    pub fn analyze(mut self, expr: &Expr) -> (Vec<Binding>, Vec<Scope>, Vec<LetInfo>) {
        self.visit_expr(expr);
        (self.bindings, self.scopes, self.lets)
    }

    fn visit_expr(&mut self, expr: &Expr) {
        match &expr.kind {
            ExprKind::Ident(name) => {
                self.mark_usage(name);
            }
            ExprKind::Literal | ExprKind::Dummy => {}
            ExprKind::Str(exprs) | ExprKind::Path(exprs) => {
                for e in exprs {
                    self.visit_expr(e);
                }
            }
            ExprKind::List(items) => {
                for e in items {
                    self.visit_expr(e);
                }
            }
            ExprKind::AttrSet { rec, entries } => {
                self.visit_attrset(*rec, entries);
            }
            ExprKind::Let {
                entries,
                body,
                let_start,
                body_start,
            } => {
                self.visit_let(entries, body, *let_start, *body_start);
            }
            ExprKind::Lambda { arg, body } => {
                self.visit_lambda(arg, body);
            }
            ExprKind::Apply(a, b) | ExprKind::Binary(a, b) => {
                self.visit_expr(a);
                self.visit_expr(b);
            }
            ExprKind::Select {
                expr,
                attrs,
                default,
            } => {
                self.visit_expr(expr);
                for a in attrs {
                    self.visit_attr_exprs(a);
                }
                if let Some(d) = default {
                    self.visit_expr(d);
                }
            }
            ExprKind::HasAttr { expr, attrs } => {
                self.visit_expr(expr);
                for a in attrs {
                    self.visit_attr_exprs(a);
                }
            }
            ExprKind::If {
                cond,
                then,
                else_,
            } => {
                self.visit_expr(cond);
                self.visit_expr(then);
                self.visit_expr(else_);
            }
            ExprKind::With { expr, body } | ExprKind::Assert { expr, body } => {
                self.visit_expr(expr);
                self.visit_expr(body);
            }
            ExprKind::Unary(e) => {
                self.visit_expr(e);
            }
        }
    }

    fn visit_attr_exprs(&mut self, attr: &Attr) {
        match attr {
            Attr::Ident { .. } => {}
            Attr::Str { exprs } => {
                for e in exprs {
                    self.visit_expr(e);
                }
            }
            Attr::Dynamic { expr } => {
                self.visit_expr(expr);
            }
        }
    }

    fn visit_let(&mut self, entries: &[Entry], body: &Expr, let_start: usize, body_start: usize) {
        let scope = self.new_scope(ScopeKind::Let);
        // create bindings
        let mut let_info = LetInfo {
            let_start,
            body_start,
            entries: Vec::new(),
            scope,
        };
        // Map entry index -> binding ids
        let mut entry_bindings: Vec<Vec<usize>> = Vec::new();
        for entry in entries {
            let mut ids = Vec::new();
            match entry {
                Entry::KeyValue {
                    attrs,
                    start,
                    end,
                    ..
                } => {
                    let stmt_id = self.next_stmt_id;
                    self.next_stmt_id += 1;
                    if let Some(Attr::Ident { name, start: ns, end: ne }) = attrs.first() {
                        let bid = self.add_binding(
                            name.clone(),
                            *ns,
                            *ne,
                            BindingKind::Let,
                            scope,
                            EditInfo::LetAssignment {
                                entry_start: *start,
                                entry_end: *end,
                            },
                        );
                        ids.push(bid);
                    }
                    let has_non_removable = !matches!(attrs.first(), Some(Attr::Ident { .. }));
                    let_info.entries.push(LetEntryInfo {
                        fully_removable_bindings: ids.clone(),
                        has_non_removable,
                        entry_start: *start,
                        entry_end: *end,
                        is_inherit_stmt: false,
                        stmt_id,
                    });
                }
                Entry::Inherit {
                    attrs,
                    start,
                    end,
                    ..
                } => {
                    let stmt_id = self.next_stmt_id;
                    self.next_stmt_id += 1;
                    let mut has_non_removable = false;
                    for attr in attrs {
                        match attr {
                            Attr::Ident { name, start: ns, end: ne } => {
                                let bid = self.add_binding(
                                    name.clone(),
                                    *ns,
                                    *ne,
                                    BindingKind::Let,
                                    scope,
                                    EditInfo::LetInherit {
                                        stmt_start: *start,
                                        stmt_end: *end,
                                        stmt_id,
                                    },
                                );
                                ids.push(bid);
                            }
                            _ => {
                                has_non_removable = true;
                            }
                        }
                    }
                    let_info.entries.push(LetEntryInfo {
                        fully_removable_bindings: ids.clone(),
                        has_non_removable,
                        entry_start: *start,
                        entry_end: *end,
                        is_inherit_stmt: true,
                        stmt_id,
                    });
                }
            }
            entry_bindings.push(ids);
        }
        self.lets.push(let_info);

        self.env.push(scope);
        for (entry, bids) in entries.iter().zip(entry_bindings.iter()) {
            match entry {
                Entry::KeyValue { attrs, value, .. } => {
                    // attrs: first ident not visited; others visited; string/dynamic first visited
                    for (i, attr) in attrs.iter().enumerate() {
                        if i == 0 && matches!(attr, Attr::Ident { .. }) {
                            continue;
                        }
                        if !bids.is_empty() {
                            self.owners.push((scope, bids[0]));
                            self.visit_attr_exprs(attr);
                            self.owners.pop();
                        } else {
                            self.visit_attr_exprs(attr);
                        }
                    }
                    if !bids.is_empty() {
                        self.owners.push((scope, bids[0]));
                        self.visit_expr(value);
                        self.owners.pop();
                    } else {
                        self.visit_expr(value);
                    }
                }
                Entry::Inherit { from, attrs, .. } => {
                    if let Some(from_expr) = from {
                        for &bid in bids.iter() {
                            self.owners.push((scope, bid));
                        }
                        self.visit_expr(from_expr);
                        for _ in bids.iter() {
                            self.owners.pop();
                        }
                        for attr in attrs {
                            if !matches!(attr, Attr::Ident { .. }) {
                                self.visit_attr_exprs(attr);
                            }
                        }
                    } else {
                        // plain inherit: usage of outer name
                        for attr in attrs {
                            match attr {
                                Attr::Ident { name, .. } => {
                                    // resolve without current let scope
                                    let env_without: Vec<usize> = self
                                        .env
                                        .iter()
                                        .cloned()
                                        .filter(|s| *s != scope)
                                        .collect();
                                    self.mark_usage_env(&env_without, name);
                                }
                                _ => self.visit_attr_exprs(attr),
                            }
                        }
                    }
                }
            }
        }
        self.visit_expr(body);
        self.env.pop();
    }

    fn visit_lambda(&mut self, arg: &LambdaArg, body: &Expr) {
        match arg {
            LambdaArg::Simple { name, start, end } => {
                let scope = self.new_scope(ScopeKind::Simple);
                self.add_binding(
                    name.clone(),
                    *start,
                    *end,
                    BindingKind::LambdaArg,
                    scope,
                    EditInfo::LambdaArg,
                );
                self.env.push(scope);
                self.visit_expr(body);
                self.env.pop();
            }
            LambdaArg::Pattern {
                entries,
                at,
                pattern_start,
                pattern_end,
            } => {
                let scope = self.new_scope(ScopeKind::Pattern);
                let mut entry_ids: Vec<usize> = Vec::new();
                for e in entries {
                    let bid = self.add_binding(
                        e.name.clone(),
                        e.start,
                        e.end,
                        BindingKind::PatternEntry,
                        scope,
                        EditInfo::PatternEntry {
                            entry_start: e.start,
                            entry_end: e.entry_end,
                            following_comma: e.following_comma,
                            is_last: e.is_last,
                        },
                    );
                    entry_ids.push(bid);
                }
                if let Some(atb) = at {
                    self.add_binding(
                        atb.name.clone(),
                        atb.start,
                        atb.end,
                        BindingKind::PatternAt,
                        scope,
                        EditInfo::PatternAt {
                            pattern_start: *pattern_start,
                            pattern_end: *pattern_end,
                            at_start: atb.at_start,
                            before_pattern: atb.before_pattern,
                        },
                    );
                }
                self.env.push(scope);
                for (e, bid) in entries.iter().zip(entry_ids.iter()) {
                    if let Some(default) = &e.default {
                        self.owners.push((scope, *bid));
                        self.visit_expr(default);
                        self.owners.pop();
                    }
                }
                self.visit_expr(body);
                self.env.pop();
            }
        }
    }

    fn visit_attrset(&mut self, rec: bool, entries: &[Entry]) {
        if rec {
            let scope = self.new_scope(ScopeKind::Rec);
            let mut entry_bindings: Vec<Vec<usize>> = Vec::new();
            for entry in entries {
                let mut ids = Vec::new();
                match entry {
                    Entry::KeyValue { attrs, .. } => {
                        if let Some(Attr::Ident { name, start, end }) = attrs.first() {
                            let bid = self.add_binding(
                                name.clone(),
                                *start,
                                *end,
                                BindingKind::Rec,
                                scope,
                                EditInfo::None,
                            );
                            ids.push(bid);
                        }
                    }
                    Entry::Inherit { attrs, .. } => {
                        for attr in attrs {
                            if let Attr::Ident { name, start, end } = attr {
                                let bid = self.add_binding(
                                    name.clone(),
                                    *start,
                                    *end,
                                    BindingKind::Rec,
                                    scope,
                                    EditInfo::None,
                                );
                                ids.push(bid);
                            }
                        }
                    }
                }
                entry_bindings.push(ids);
            }
            self.env.push(scope);
            for (entry, bids) in entries.iter().zip(entry_bindings.iter()) {
                match entry {
                    Entry::KeyValue { attrs, value, .. } => {
                        for (i, attr) in attrs.iter().enumerate() {
                            if i == 0 && matches!(attr, Attr::Ident { .. }) {
                                continue;
                            }
                            self.visit_attr_exprs(attr);
                        }
                        if !bids.is_empty() {
                            self.owners.push((scope, bids[0]));
                            self.visit_expr(value);
                            self.owners.pop();
                        } else {
                            self.visit_expr(value);
                        }
                    }
                    Entry::Inherit { from, attrs, .. } => {
                        if let Some(from_expr) = from {
                            for &bid in bids.iter() {
                                self.owners.push((scope, bid));
                            }
                            self.visit_expr(from_expr);
                            for _ in bids.iter() {
                                self.owners.pop();
                            }
                            for attr in attrs {
                                match attr {
                                    Attr::Ident { name, .. } => {
                                        self.mark_usage(name);
                                    }
                                    _ => self.visit_attr_exprs(attr),
                                }
                            }
                        } else {
                            for attr in attrs {
                                match attr {
                                    Attr::Ident { name, .. } => {
                                        let env_without: Vec<usize> = self
                                            .env
                                            .iter()
                                            .cloned()
                                            .filter(|s| *s != scope)
                                            .collect();
                                        self.mark_usage_env(&env_without, name);
                                    }
                                    _ => self.visit_attr_exprs(attr),
                                }
                            }
                        }
                    }
                }
            }
            self.env.pop();
        } else {
            for entry in entries {
                match entry {
                    Entry::KeyValue { attrs, value, .. } => {
                        for attr in attrs.iter() {
                            self.visit_attr_exprs(attr);
                        }
                        self.visit_expr(value);
                    }
                    Entry::Inherit { from, attrs, .. } => {
                        if let Some(from_expr) = from {
                            self.visit_expr(from_expr);
                        }
                        for attr in attrs {
                            match attr {
                                Attr::Ident { name, .. } => {
                                    self.mark_usage(name);
                                }
                                _ => self.visit_attr_exprs(attr),
                            }
                        }
                    }
                }
            }
        }
    }
}

pub fn compute_results(
    bindings: &[Binding],
    scopes: &[Scope],
    opts: &Options,
) -> Vec<ResultBinding> {
    // pattern duplicate counts
    let mut pattern_counts: HashMap<(usize, String), usize> = HashMap::new();
    for b in bindings {
        if b.kind == BindingKind::PatternEntry {
            *pattern_counts
                .entry((b.scope, b.name.clone()))
                .or_insert(0) += 1;
        }
    }

    // per scope candidate sets
    let mut alive_normal: HashMap<usize, HashSet<usize>> = HashMap::new();
    let mut alive_warn: HashMap<usize, HashSet<usize>> = HashMap::new();
    for scope in scopes {
        if scope.kind == ScopeKind::Rec {
            continue;
        }
        alive_normal.insert(scope.id, compute_alive(bindings, scope, false, opts));
        alive_warn.insert(scope.id, compute_alive(bindings, scope, true, opts));
    }

    let mut results = Vec::new();
    for b in bindings {
        if b.kind == BindingKind::Rec {
            continue;
        }
        if b.skipped {
            continue;
        }
        let is_underscore = b.name.starts_with('_');
        if b.kind == BindingKind::LambdaArg && (opts.no_lambda_arg || is_underscore) {
            continue;
        }
        if is_underscore && opts.no_underscore && b.kind != BindingKind::LambdaArg {
            continue;
        }
        if b.kind == BindingKind::PatternEntry && opts.no_lambda_pattern_names {
            continue;
        }
        let duplicate_pattern = b.kind == BindingKind::PatternEntry
            && pattern_counts
                .get(&(b.scope, b.name.clone()))
                .map(|c| *c > 1)
                .unwrap_or(false);

        let (is_used_class, force_unused): (bool, bool) = if opts.warn_used_underscore && is_underscore
            && b.kind != BindingKind::LambdaArg
        {
            // Used if root or a user in warn-alive set
            let warn_set = alive_warn.get(&b.scope).cloned().unwrap_or_default();
            let used = b.root_used || b.users.iter().any(|u| warn_set.contains(u));
            (used, !used)
        } else {
            (false, false)
        };

        if opts.warn_used_underscore && is_underscore && b.kind != BindingKind::LambdaArg {
            // duplicate pattern entries: still reported in -W mode per probes
            let msg_kind = if is_used_class { "Used" } else { "Unused" };
            results.push(ResultBinding {
                name: b.name.clone(),
                start: b.start,
                end: b.end,
                kind: b.kind,
                message: format!("{} {}: {}", msg_kind, b.kind.label(), b.name),
                binding_id: b.id,
            });
            let _ = force_unused;
            continue;
        }
        if duplicate_pattern {
            continue;
        }
        let alive = if opts.warn_used_underscore {
            alive_warn
                .get(&b.scope)
                .map(|s| s.contains(&b.id))
                .unwrap_or(false)
        } else {
            alive_normal
                .get(&b.scope)
                .map(|s| s.contains(&b.id))
                .unwrap_or(false)
        };
        if !alive {
            results.push(ResultBinding {
                name: b.name.clone(),
                start: b.start,
                end: b.end,
                kind: b.kind,
                message: format!("Unused {}: {}", b.kind.label(), b.name),
                binding_id: b.id,
            });
        }
    }
    results.sort_by_key(|r| r.start);
    results
}

fn compute_alive(
    bindings: &[Binding],
    scope: &Scope,
    warn_mode: bool,
    _opts: &Options,
) -> HashSet<usize> {
    let by_id: HashMap<usize, &Binding> = bindings.iter().map(|b| (b.id, b)).collect();
    let mut candidate: HashSet<usize> = HashSet::new();
    for &bid in &scope.bindings {
        let b = by_id[&bid];
        if warn_mode && b.name.starts_with('_') && !b.skipped {
            continue;
        }
        candidate.insert(bid);
    }
    // skipped bindings are forced
    for &bid in &scope.bindings {
        if by_id[&bid].skipped {
            candidate.insert(bid);
        }
    }
    loop {
        let mut to_remove = Vec::new();
        for &bid in candidate.iter() {
            let b = by_id[&bid];
            if b.skipped {
                continue;
            }
            if b.root_used {
                continue;
            }
            if b.users.iter().any(|u| candidate.contains(u)) {
                continue;
            }
            to_remove.push(bid);
        }
        if to_remove.is_empty() {
            break;
        }
        for bid in to_remove {
            candidate.remove(&bid);
        }
    }
    candidate
}
RS"}

actions.command:
cat > src/analysis.rs <<'RS'
use crate::lexer::Token;
use crate::parser::{Attr, AtBind, Entry, Expr, ExprKind, LambdaArg, PatEntry};
use std::collections::{HashMap, HashSet};

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum BindingKind {
    Let,
    LambdaArg,
    PatternEntry,
    PatternAt,
    Rec,
}

impl BindingKind {
    pub fn label(self) -> &'static str {
        match self {
            BindingKind::Let => "let binding",
            BindingKind::LambdaArg => "lambda argument",
            BindingKind::PatternEntry | BindingKind::PatternAt => "lambda pattern",
            BindingKind::Rec => "let binding",
        }
    }
    pub fn color_code(self) -> u32 {
        match self {
            BindingKind::Let | BindingKind::Rec => 31,
            BindingKind::PatternEntry | BindingKind::PatternAt => 35,
            BindingKind::LambdaArg => 36,
        }
    }
}

#[derive(Clone, Debug)]
pub enum EditInfo {
    LetAssignment {
        entry_start: usize,
        entry_end: usize,
    },
    LetInherit {
        stmt_start: usize,
        stmt_end: usize,
        stmt_id: usize,
    },
    PatternEntry {
        entry_start: usize,
        entry_end: usize,
        following_comma: bool,
        is_last: bool,
    },
    PatternAt {
        pattern_start: usize,
        pattern_end: usize,
        at_start: usize,
        before_pattern: bool,
    },
    LambdaArg,
    None,
}

#[derive(Clone, Debug)]
pub struct Binding {
    pub id: usize,
    pub name: String,
    pub start: usize,
    pub end: usize,
    pub kind: BindingKind,
    pub scope: usize,
    pub skipped: bool,
    pub root_used: bool,
    pub users: HashSet<usize>,
    pub edit: EditInfo,
}

#[derive(Clone, Debug)]
pub struct LetEntryInfo {
    pub fully_removable_bindings: Vec<usize>, // binding ids if this entry can be removed when all are results; empty if not removable
    pub has_non_removable: bool,
    pub entry_start: usize,
    pub entry_end: usize,
    pub is_inherit_stmt: bool,
    pub stmt_id: usize,
}

#[derive(Clone, Debug)]
pub struct LetInfo {
    pub let_start: usize,
    pub body_start: usize,
    pub entries: Vec<LetEntryInfo>,
    pub scope: usize,
}

#[derive(Clone, Debug)]
pub struct Scope {
    pub id: usize,
    pub bindings: Vec<usize>,
    #[allow(dead_code)]
    pub kind: ScopeKind,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum ScopeKind {
    Let,
    Pattern,
    Simple,
    Rec,
}

pub struct Analyzer<'a> {
    pub src: &'a str,
    pub bindings: Vec<Binding>,
    pub scopes: Vec<Scope>,
    pub lets: Vec<LetInfo>,
    comments: Vec<(usize, usize)>, // start,end byte of comments
    env: Vec<usize>,
    owners: Vec<(usize, usize)>, // (scope, binding)
    next_stmt_id: usize,
}

#[derive(Clone)]
pub struct Options {
    pub no_lambda_arg: bool,
    pub no_lambda_pattern_names: bool,
    pub no_underscore: bool,
    pub warn_used_underscore: bool,
}

#[derive(Clone, Debug)]
pub struct ResultBinding {
    pub name: String,
    pub start: usize,
    pub end: usize,
    pub kind: BindingKind,
    pub message: String,
    pub binding_id: usize,
}

impl<'a> Analyzer<'a> {
    pub fn new(src: &'a str, comments: &[Token]) -> Self {
        Analyzer {
            src,
            bindings: Vec::new(),
            scopes: Vec::new(),
            lets: Vec::new(),
            comments: comments.iter().map(|t| (t.start, t.end)).collect(),
            env: Vec::new(),
            owners: Vec::new(),
            next_stmt_id: 0,
        }
    }

    fn is_skipped(&self, name_start: usize) -> bool {
        // line of name_start (1-based)
        let line_of = |pos: usize| -> usize {
            self.src[..pos].bytes().filter(|&b| b == b'\n').count() + 1
        };
        let bline = line_of(name_start);
        for (cs, ce) in &self.comments {
            let text = &self.src[*cs..*ce];
            if !text.contains("deadnix: skip") {
                continue;
            }
            if name_start <= *ce {
                continue;
            }
            let cline_end = line_of(*ce);
            if bline == cline_end || bline == cline_end + 1 {
                return true;
            }
        }
        false
    }

    fn new_scope(&mut self, kind: ScopeKind) -> usize {
        let id = self.scopes.len();
        self.scopes.push(Scope {
            id,
            bindings: Vec::new(),
            kind,
        });
        id
    }

    fn add_binding(
        &mut self,
        name: String,
        start: usize,
        end: usize,
        kind: BindingKind,
        scope: usize,
        edit: EditInfo,
    ) -> usize {
        let id = self.bindings.len();
        let skipped = self.is_skipped(start);
        self.bindings.push(Binding {
            id,
            name,
            start,
            end,
            kind,
            scope,
            skipped,
            root_used: false,
            users: HashSet::new(),
            edit,
        });
        self.scopes[scope].bindings.push(id);
        id
    }

    fn resolve_in_env(&self, env: &[usize], name: &str) -> Option<(usize, Vec<usize>)> {
        for scope_id in env.iter().rev() {
            let ids: Vec<usize> = self.scopes[*scope_id]
                .bindings
                .iter()
                .cloned()
                .filter(|bid| self.bindings[*bid].name == name)
                .collect();
            if !ids.is_empty() {
                return Some((*scope_id, ids));
            }
        }
        None
    }

    fn mark_usage_env(&mut self, env: &[usize], name: &str) {
        if let Some((_scope, ids)) = self.resolve_in_env(env, name) {
            self.mark_ids(&ids);
        }
    }

    fn mark_ids(&mut self, ids: &[usize]) {
        for &tid in ids {
            let tscope = self.bindings[tid].scope;
            let owners_for_scope: Vec<usize> = self
                .owners
                .iter()
                .filter(|(s, _)| *s == tscope)
                .map(|(_, b)| *b)
                .collect();
            if owners_for_scope.is_empty() {
                self.bindings[tid].root_used = true;
            } else {
                for owner in owners_for_scope {
                    if owner != tid {
                        self.bindings[tid].users.insert(owner);
                    }
                }
            }
        }
    }

    fn mark_usage(&mut self, name: &str) {
        let env = self.env.clone();
        self.mark_usage_env(&env, name);
    }

    pub fn analyze(mut self, expr: &Expr) -> (Vec<Binding>, Vec<Scope>, Vec<LetInfo>) {
        self.visit_expr(expr);
        (self.bindings, self.scopes, self.lets)
    }

    fn visit_expr(&mut self, expr: &Expr) {
        match &expr.kind {
            ExprKind::Ident(name) => {
                self.mark_usage(name);
            }
            ExprKind::Literal | ExprKind::Dummy => {}
            ExprKind::Str(exprs) | ExprKind::Path(exprs) => {
                for e in exprs {
                    self.visit_expr(e);
                }
            }
            ExprKind::List(items) => {
                for e in items {
                    self.visit_expr(e);
                }
            }
            ExprKind::AttrSet { rec, entries } => {
                self.visit_attrset(*rec, entries);
            }
            ExprKind::Let {
                entries,
                body,
                let_start,
                body_start,
            } => {
                self.visit_let(entries, body, *let_start, *body_start);
            }
            ExprKind::Lambda { arg, body } => {
                self.visit_lambda(arg, body);
            }
            ExprKind::Apply(a, b) | ExprKind::Binary(a, b) => {
                self.visit_expr(a);
                self.visit_expr(b);
            }
            ExprKind::Select {
                expr,
                attrs,
                default,
            } => {
                self.visit_expr(expr);
                for a in attrs {
                    self.visit_attr_exprs(a);
                }
                if let Some(d) = default {
                    self.visit_expr(d);
                }
            }
            ExprKind::HasAttr { expr, attrs } => {
                self.visit_expr(expr);
                for a in attrs {
                    self.visit_attr_exprs(a);
                }
            }
            ExprKind::If {
                cond,
                then,
                else_,
            } => {
                self.visit_expr(cond);
                self.visit_expr(then);
                self.visit_expr(else_);
            }
            ExprKind::With { expr, body } | ExprKind::Assert { expr, body } => {
                self.visit_expr(expr);
                self.visit_expr(body);
            }
            ExprKind::Unary(e) => {
                self.visit_expr(e);
            }
        }
    }

    fn visit_attr_exprs(&mut self, attr: &Attr) {
        match attr {
            Attr::Ident { .. } => {}
            Attr::Str { exprs } => {
                for e in exprs {
                    self.visit_expr(e);
                }
            }
            Attr::Dynamic { expr } => {
                self.visit_expr(expr);
            }
        }
    }

    fn visit_let(&mut self, entries: &[Entry], body: &Expr, let_start: usize, body_start: usize) {
        let scope = self.new_scope(ScopeKind::Let);
        // create bindings
        let mut let_info = LetInfo {
            let_start,
            body_start,
            entries: Vec::new(),
            scope,
        };
        // Map entry index -> binding ids
        let mut entry_bindings: Vec<Vec<usize>> = Vec::new();
        for entry in entries {
            let mut ids = Vec::new();
            match entry {
                Entry::KeyValue {
                    attrs,
                    start,
                    end,
                    ..
                } => {
                    let stmt_id = self.next_stmt_id;
                    self.next_stmt_id += 1;
                    if let Some(Attr::Ident { name, start: ns, end: ne }) = attrs.first() {
                        let bid = self.add_binding(
                            name.clone(),
                            *ns,
                            *ne,
                            BindingKind::Let,
                            scope,
                            EditInfo::LetAssignment {
                                entry_start: *start,
                                entry_end: *end,
                            },
                        );
                        ids.push(bid);
                    }
                    let has_non_removable = !matches!(attrs.first(), Some(Attr::Ident { .. }));
                    let_info.entries.push(LetEntryInfo {
                        fully_removable_bindings: ids.clone(),
                        has_non_removable,
                        entry_start: *start,
                        entry_end: *end,
                        is_inherit_stmt: false,
                        stmt_id,
                    });
                }
                Entry::Inherit {
                    attrs,
                    start,
                    end,
                    ..
                } => {
                    let stmt_id = self.next_stmt_id;
                    self.next_stmt_id += 1;
                    let mut has_non_removable = false;
                    for attr in attrs {
                        match attr {
                            Attr::Ident { name, start: ns, end: ne } => {
                                let bid = self.add_binding(
                                    name.clone(),
                                    *ns,
                                    *ne,
                                    BindingKind::Let,
                                    scope,
                                    EditInfo::LetInherit {
                                        stmt_start: *start,
                                        stmt_end: *end,
                                        stmt_id,
                                    },
                                );
                                ids.push(bid);
                            }
                            _ => {
                                has_non_removable = true;
                            }
                        }
                    }
                    let_info.entries.push(LetEntryInfo {
                        fully_removable_bindings: ids.clone(),
                        has_non_removable,
                        entry_start: *start,
                        entry_end: *end,
                        is_inherit_stmt: true,
                        stmt_id,
                    });
                }
            }
            entry_bindings.push(ids);
        }
        self.lets.push(let_info);

        self.env.push(scope);
        for (entry, bids) in entries.iter().zip(entry_bindings.iter()) {
            match entry {
                Entry::KeyValue { attrs, value, .. } => {
                    // attrs: first ident not visited; others visited; string/dynamic first visited
                    for (i, attr) in attrs.iter().enumerate() {
                        if i == 0 && matches!(attr, Attr::Ident { .. }) {
                            continue;
                        }
                        if !bids.is_empty() {
                            self.owners.push((scope, bids[0]));
                            self.visit_attr_exprs(attr);
                            self.owners.pop();
                        } else {
                            self.visit_attr_exprs(attr);
                        }
                    }
                    if !bids.is_empty() {
                        self.owners.push((scope, bids[0]));
                        self.visit_expr(value);
                        self.owners.pop();
                    } else {
                        self.visit_expr(value);
                    }
                }
                Entry::Inherit { from, attrs, .. } => {
                    if let Some(from_expr) = from {
                        for &bid in bids.iter() {
                            self.owners.push((scope, bid));
                        }
                        self.visit_expr(from_expr);
                        for _ in bids.iter() {
                            self.owners.pop();
                        }
                        for attr in attrs {
                            if !matches!(attr, Attr::Ident { .. }) {
                                self.visit_attr_exprs(attr);
                            }
                        }
                    } else {
                        // plain inherit: usage of outer name
                        for attr in attrs {
                            match attr {
                                Attr::Ident { name, .. } => {
                                    // resolve without current let scope
                                    let env_without: Vec<usize> = self
                                        .env
                                        .iter()
                                        .cloned()
                                        .filter(|s| *s != scope)
                                        .collect();
                                    self.mark_usage_env(&env_without, name);
                                }
                                _ => self.visit_attr_exprs(attr),
                            }
                        }
                    }
                }
            }
        }
        self.visit_expr(body);
        self.env.pop();
    }

    fn visit_lambda(&mut self, arg: &LambdaArg, body: &Expr) {
        match arg {
            LambdaArg::Simple { name, start, end } => {
                let scope = self.new_scope(ScopeKind::Simple);
                self.add_binding(
                    name.clone(),
                    *start,
                    *end,
                    BindingKind::LambdaArg,
                    scope,
                    EditInfo::LambdaArg,
                );
                self.env.push(scope);
                self.visit_expr(body);
                self.env.pop();
            }
            LambdaArg::Pattern {
                entries,
                at,
                pattern_start,
                pattern_end,
            } => {
                let scope = self.new_scope(ScopeKind::Pattern);
                let mut entry_ids: Vec<usize> = Vec::new();
                for e in entries {
                    let bid = self.add_binding(
                        e.name.clone(),
                        e.start,
                        e.end,
                        BindingKind::PatternEntry,
                        scope,
                        EditInfo::PatternEntry {
                            entry_start: e.start,
                            entry_end: e.entry_end,
                            following_comma: e.following_comma,
                            is_last: e.is_last,
                        },
                    );
                    entry_ids.push(bid);
                }
                if let Some(atb) = at {
                    self.add_binding(
                        atb.name.clone(),
                        atb.start,
                        atb.end,
                        BindingKind::PatternAt,
                        scope,
                        EditInfo::PatternAt {
                            pattern_start: *pattern_start,
                            pattern_end: *pattern_end,
                            at_start: atb.at_start,
                            before_pattern: atb.before_pattern,
                        },
                    );
                }
                self.env.push(scope);
                for (e, bid) in entries.iter().zip(entry_ids.iter()) {
                    if let Some(default) = &e.default {
                        self.owners.push((scope, *bid));
                        self.visit_expr(default);
                        self.owners.pop();
                    }
                }
                self.visit_expr(body);
                self.env.pop();
            }
        }
    }

    fn visit_attrset(&mut self, rec: bool, entries: &[Entry]) {
        if rec {
            let scope = self.new_scope(ScopeKind::Rec);
            let mut entry_bindings: Vec<Vec<usize>> = Vec::new();
            for entry in entries {
                let mut ids = Vec::new();
                match entry {
                    Entry::KeyValue { attrs, .. } => {
                        if let Some(Attr::Ident { name, start, end }) = attrs.first() {
                            let bid = self.add_binding(
                                name.clone(),
                                *start,
                                *end,
                                BindingKind::Rec,
                                scope,
                                EditInfo::None,
                            );
                            ids.push(bid);
                        }
                    }
                    Entry::Inherit { attrs, .. } => {
                        for attr in attrs {
                            if let Attr::Ident { name, start, end } = attr {
                                let bid = self.add_binding(
                                    name.clone(),
                                    *start,
                                    *end,
                                    BindingKind::Rec,
                                    scope,
                                    EditInfo::None,
                                );
                                ids.push(bid);
                            }
                        }
                    }
                }
                entry_bindings.push(ids);
            }
            self.env.push(scope);
            for (entry, bids) in entries.iter().zip(entry_bindings.iter()) {
                match entry {
                    Entry::KeyValue { attrs, value, .. } => {
                        for (i, attr) in attrs.iter().enumerate() {
                            if i == 0 && matches!(attr, Attr::Ident { .. }) {
                                continue;
                            }
                            self.visit_attr_exprs(attr);
                        }
                        if !bids.is_empty() {
                            self.owners.push((scope, bids[0]));
                            self.visit_expr(value);
                            self.owners.pop();
                        } else {
                            self.visit_expr(value);
                        }
                    }
                    Entry::Inherit { from, attrs, .. } => {
                        if let Some(from_expr) = from {
                            for &bid in bids.iter() {
                                self.owners.push((scope, bid));
                            }
                            self.visit_expr(from_expr);
                            for _ in bids.iter() {
                                self.owners.pop();
                            }
                            for attr in attrs {
                                match attr {
                                    Attr::Ident { name, .. } => {
                                        self.mark_usage(name);
                                    }
                                    _ => self.visit_attr_exprs(attr),
                                }
                            }
                        } else {
                            for attr in attrs {
                                match attr {
                                    Attr::Ident { name, .. } => {
                                        let env_without: Vec<usize> = self
                                            .env
                                            .iter()
                                            .cloned()
                                            .filter(|s| *s != scope)
                                            .collect();
                                        self.mark_usage_env(&env_without, name);
                                    }
                                    _ => self.visit_attr_exprs(attr),
                                }
                            }
                        }
                    }
                }
            }
            self.env.pop();
        } else {
            for entry in entries {
                match entry {
                    Entry::KeyValue { attrs, value, .. } => {
                        for attr in attrs.iter() {
                            self.visit_attr_exprs(attr);
                        }
                        self.visit_expr(value);
                    }
                    Entry::Inherit { from, attrs, .. } => {
                        if let Some(from_expr) = from {
                            self.visit_expr(from_expr);
                        }
                        for attr in attrs {
                            match attr {
                                Attr::Ident { name, .. } => {
                                    self.mark_usage(name);
                                }
                                _ => self.visit_attr_exprs(attr),
                            }
                        }
                    }
                }
            }
        }
    }
}

pub fn compute_results(
    bindings: &[Binding],
    scopes: &[Scope],
    opts: &Options,
) -> Vec<ResultBinding> {
    // pattern duplicate counts
    let mut pattern_counts: HashMap<(usize, String), usize> = HashMap::new();
    for b in bindings {
        if b.kind == BindingKind::PatternEntry {
            *pattern_counts
                .entry((b.scope, b.name.clone()))
                .or_insert(0) += 1;
        }
    }

    // per scope candidate sets
    let mut alive_normal: HashMap<usize, HashSet<usize>> = HashMap::new();
    let mut alive_warn: HashMap<usize, HashSet<usize>> = HashMap::new();
    for scope in scopes {
        if scope.kind == ScopeKind::Rec {
            continue;
        }
        alive_normal.insert(scope.id, compute_alive(bindings, scope, false, opts));
        alive_warn.insert(scope.id, compute_alive(bindings, scope, true, opts));
    }

    let mut results = Vec::new();
    for b in bindings {
        if b.kind == BindingKind::Rec {
            continue;
        }
        if b.skipped {
            continue;
        }
        let is_underscore = b.name.starts_with('_');
        if b.kind == BindingKind::LambdaArg && (opts.no_lambda_arg || is_underscore) {
            continue;
        }
        if is_underscore && opts.no_underscore && b.kind != BindingKind::LambdaArg {
            continue;
        }
        if b.kind == BindingKind::PatternEntry && opts.no_lambda_pattern_names {
            continue;
        }
        let duplicate_pattern = b.kind == BindingKind::PatternEntry
            && pattern_counts
                .get(&(b.scope, b.name.clone()))
                .map(|c| *c > 1)
                .unwrap_or(false);

        let (is_used_class, force_unused): (bool, bool) = if opts.warn_used_underscore && is_underscore
            && b.kind != BindingKind::LambdaArg
        {
            // Used if root or a user in warn-alive set
            let warn_set = alive_warn.get(&b.scope).cloned().unwrap_or_default();
            let used = b.root_used || b.users.iter().any(|u| warn_set.contains(u));
            (used, !used)
        } else {
            (false, false)
        };

        if opts.warn_used_underscore && is_underscore && b.kind != BindingKind::LambdaArg {
            // duplicate pattern entries: still reported in -W mode per probes
            let msg_kind = if is_used_class { "Used" } else { "Unused" };
            results.push(ResultBinding {
                name: b.name.clone(),
                start: b.start,
                end: b.end,
                kind: b.kind,
                message: format!("{} {}: {}", msg_kind, b.kind.label(), b.name),
                binding_id: b.id,
            });
            let _ = force_unused;
            continue;
        }
        if duplicate_pattern {
            continue;
        }
        let alive = if opts.warn_used_underscore {
            alive_warn
                .get(&b.scope)
                .map(|s| s.contains(&b.id))
                .unwrap_or(false)
        } else {
            alive_normal
                .get(&b.scope)
                .map(|s| s.contains(&b.id))
                .unwrap_or(false)
        };
        if !alive {
            results.push(ResultBinding {
                name: b.name.clone(),
                start: b.start,
                end: b.end,
                kind: b.kind,
                message: format!("Unused {}: {}", b.kind.label(), b.name),
                binding_id: b.id,
            });
        }
    }
    results.sort_by_key(|r| r.start);
    results
}

fn compute_alive(
    bindings: &[Binding],
    scope: &Scope,
    warn_mode: bool,
    _opts: &Options,
) -> HashSet<usize> {
    let by_id: HashMap<usize, &Binding> = bindings.iter().map(|b| (b.id, b)).collect();
    let mut candidate: HashSet<usize> = HashSet::new();
    for &bid in &scope.bindings {
        let b = by_id[&bid];
        if warn_mode && b.name.starts_with('_') && !b.skipped {
            continue;
        }
        candidate.insert(bid);
    }
    // skipped bindings are forced
    for &bid in &scope.bindings {
        if by_id[&bid].skipped {
            candidate.insert(bid);
        }
    }
    loop {
        let mut to_remove = Vec::new();
        for &bid in candidate.iter() {
            let b = by_id[&bid];
            if b.skipped {
                continue;
            }
            if b.root_used {
                continue;
            }
            if b.users.iter().any(|u| candidate.contains(u)) {
                continue;
            }
            to_remove.push(bid);
        }
        if to_remove.is_empty() {
            break;
        }
        for bid in to_remove {
            candidate.remove(&bid);
        }
    }
    candidate
}
RS

