                            if !e.has_non_removable
                                && !e.fully_removable_bindings.is_empty()
                                && e.fully_removable_bindings
                                    .iter()
                                    .all(|bid| result_ids.contains(bid))
                            {
                                stmt_fully_removed = true;
                            }
                        }
