                    ops.push(Op::Remove {
                        start: b.start,
                        end: *pattern_start,
                    });
                } else {
                    ops.push(Op::Remove {
                        start: *at_start,
                        end: b.end,
                    });
                }
            }
            EditInfo::None => {}
        }
    }

    // Sort by start, longer first
    ops.sort_by(|a, b| {
        a.start()
            .cmp(&b.start())
            .then_with(|| b.end().cmp(&a.end()))
    });

    let mut out = String::new();
    let mut cursor = 0usize;
    for op in &ops {
        if op.start() < cursor {
            if op.end() <= cursor {
                continue;
            } else {
                return Err(EditPanic {
                    begin: cursor,
                    end: op.start(),
                });
            }
        }
        out.push_str(&src[cursor..op.start()]);
        match op {
            Op::Remove { .. } => {}
            Op::Replace { text, .. } => out.push_str(text),
        }
        cursor = op.end();
    }
    out.push_str(&src[cursor..]);
    Ok(out)
}
