                // Determine color per position
                for pos in 0..msg_col {
                    let ch = row_str.chars().nth(pos).unwrap_or(' ');
                    if ch == ' ' {
                        colored.push(' ');
                    } else if ch == '│' {
                        // find pending label with this mid
                        let mut code = label.result.kind.color_code();
                        for &oi in order.iter().skip(row_pos + 1) {
                            if labels[oi].mid == pos {
                                code = labels[oi].result.kind.color_code();
                                break;
                            }
                        }
                        colored.push_str(&format!("\x1b[{}m{}\x1b[0m", code, ch));
                    } else if ch == '╰' || ch == '─' {
                        // Avoid unused variable warning for buf_chars
                        let _ = &buf_chars;
                        colored.push_str(&format!(
                            "\x1b[{}m{}\x1b[0m",
                            label.result.kind.color_code(),
                            ch
                        ));
                    } else {
                        colored.push(ch);
                    }
                }
                out.push_str(&colored);
                out.push_str(&label.result.message);
                out.push('\n');
            } else {
                out.push_str(&format!("{}│{}\n", " ".repeat(digits + 2), row_str));
            }
        }
    }
    print!("{}", out);
}
