use crate::analysis::ResultBinding;
use std::collections::BTreeMap;

fn char_width(c: char) -> usize {
    // Simplified unicode width: combining marks 0, wide/fullwidth 2, else 1, tab handled separately
    if c == '\u{200b}' {
        return 0;
    }
    let cp = c as u32;
    // combining diacriticals ranges
    if (0x0300..0x0370).contains(&cp)
        || (0x1ab0..0x1b00).contains(&cp)
        || (0x1dc0..0x1e00).contains(&cp)
        || (0x20d0..0x2100).contains(&cp)
        || (0xfe20..0xfe30).contains(&cp)
    {
        return 0;
    }
    if (0x1100..0x1160).contains(&cp)
        || (0x2e80..0xa4cf).contains(&cp)
        || (0xac00..0xd7a3).contains(&cp)
        || (0xf900..0xfaff).contains(&cp)
        || (0xfe30..0xfe6f).contains(&cp)
        || (0xff00..0xff60).contains(&cp)
        || (0xffe0..0xffe6).contains(&cp)
        || (0x1f300..0x1f650).contains(&cp)
        || (0x1f900..0x1f9ff).contains(&cp)
        || (0x20000..0x2fffd).contains(&cp)
        || (0x30000..0x3fffd).contains(&cp)
    {
        return 2;
    }
    1
}

fn visual_width_str(s: &str) -> usize {
    let mut w = 0usize;
    let mut col = 0usize;
    for c in s.chars() {
        if c == '\t' {
            let adv = 4 - (col % 4);
            col += adv;
            w += adv;
        } else {
            let cw = char_width(c);
            col += cw;
            w += cw;
        }
    }
    w
}

fn expand_tabs(s: &str) -> String {
    let mut out = String::new();
    let mut col = 0usize;
    for c in s.chars() {
        if c == '\t' {
            let adv = 4 - (col % 4);
            for _ in 0..adv {
                out.push(' ');
            }
            col += adv;
        } else {
            out.push(c);
            col += char_width(c);
        }
    }
    out
}

struct LineCol {
    line: usize,        // 1-based
    col_byte: usize,    // byte offset within line
    line_start: usize,  // byte index in source
}

fn line_col(src: &str, pos: usize) -> LineCol {
    let mut line = 1usize;
    let mut line_start = 0usize;
    for (i, b) in src.bytes().enumerate() {
        if i >= pos {
            break;
        }
        if b == b'\n' {
            line += 1;
            line_start = i + 1;
        }
    }
    LineCol {
        line,
        col_byte: pos - line_start,
        line_start,
    }
}

pub fn result_line_col(src: &str, r: &ResultBinding) -> (usize, usize, usize) {
    // (line, column, endColumn) with byte-based columns as original
    let lc = line_col(src, r.start);
    let line_start = lc.line_start;
    let col = r.start - line_start + 1;
    let end_col = r.end - line_start + 1;
    (lc.line, col, end_col)
}

pub fn print_human(src: &str, file_display: &str, results: &[ResultBinding], use_color: bool) {
    if results.is_empty() {
        return;
    }
    // Build line info
    let mut line_nums: Vec<usize> = Vec::new();
    for r in results {
        let (line, _, _) = result_line_col(src, r);
        line_nums.push(line);
    }
    let max_line = *line_nums.iter().max().unwrap_or(&1);
    let digits = format!("{}", max_line).len();

    let mut out = String::new();
    // Header
    if use_color {
        out.push_str("\x1b[33mWarning:\x1b[0m Unused declarations were found.\n");
    } else {
        out.push_str("Warning: Unused declarations were found.\n");
    }
    let (first_line, first_col, _) = result_line_col(src, &results[0]);
    if use_color {
        out.push_str(&" ".repeat(digits + 2));
