{"command":"cat > src/main.rs <<'RS'
mod analysis;
mod edit;
mod lexer;
mod parser;
mod report;

use analysis::{compute_results, Analyzer, Options};
use clap::{Arg, ArgAction, Command};
use serde::Serialize;
use std::collections::HashSet;
use std::path::{Path, PathBuf};
use std::process::ExitCode;
use walkdir::WalkDir;

#[derive(Clone, Copy, PartialEq, Eq)]
enum OutputFormat {
    HumanReadable,
    Json,
}

#[derive(Serialize)]
struct JsonReport<'a> {
    file: &'a Path,
    results: Vec<JsonResult>,
}

#[derive(Serialize)]
struct JsonResult {
    #[serde(skip_serializing_if = "Option::is_none")]
    column: Option<usize>,
    #[serde(rename = "endColumn", skip_serializing_if = "Option::is_none")]
    end_column: Option<usize>,
    #[serde(skip_serializing_if = "Option::is_none")]
    line: Option<usize>,
    message: String,
}

fn panic_print(location: &str, payload: String) -> ! {
    eprintln!(
        "\nthread 'main' ({}) panicked at {}:\n{}\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace",
        std::process::id(),
        location,
        payload
    );
    std::process::exit(101);
}

struct Config {
    file_paths: Vec<PathBuf>,
    no_lambda_arg: bool,
    no_lambda_pattern_names: bool,
    no_underscore: bool,
    warn_used_underscore: bool,
    quiet: bool,
    edit: bool,
    hidden: bool,
    fail: bool,
    output_format: OutputFormat,
    excludes: Vec<PathBuf>,
}

fn build_cli() -> Command {
    Command::new("deadnix")
        .version("1.3.1")
        .about("Find dead code in .nix files")
        .disable_help_flag(true)
        .disable_version_flag(true)
        .arg(
            Arg::new("file_paths")
                .help(".nix files, or directories with .nix files inside")
                .default_value(".")
                .num_args(0..)
                .value_name("FILE_PATHS")
                .value_parser(clap::value_parser!(PathBuf)),
        )
        .arg(
            Arg::new("no_lambda_arg")
                .short('l')
                .long("no-lambda-arg")
                .help("Don't check lambda parameter arguments")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("no_lambda_pattern_names")
                .short('L')
                .long("no-lambda-pattern-names")
                .help("Don't check lambda attrset pattern names (don't break nixpkgs callPackage)")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("no_underscore")
                .short('_')
                .long("no-underscore")
                .help("Don't check any bindings that start with a _\n(Lambda arguments starting with _ are not checked anyway.)")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("warn_used_underscore")
                .short('W')
                .long("warn-used-underscore")
                .help("Warn if bindings are referenced that start with '_'")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("quiet")
                .short('q')
                .long("quiet")
                .help("Don't print dead code report")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("edit")
                .short('e')
                .long("edit")
                .help("Remove unused code and write to source file")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("hidden")
                .short('h')
                .long("hidden")
                .help("Recurse into hidden subdirectories and process hidden .*.nix files")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("help")
                .long("help")
                .help("")
                .action(ArgAction::Help),
        )
        .arg(
            Arg::new("fail")
                .short('f')
                .long("fail")
                .help("Exit with 1 if unused code has been found")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("output_format")
                .short('o')
                .long("output-format")
                .help("Output format to use")
                .default_value("human-readable")
                .value_parser(["human-readable", "json"])
                .value_name("OUTPUT_FORMAT"),
        )
        .arg(
            Arg::new("excludes")
                .long("exclude")
                .help("Files to exclude from analysis")
                .num_args(1..)
                .value_name("EXCLUDES")
                .value_parser(clap::value_parser!(PathBuf)),
        )
        .arg(
            Arg::new("version")
                .short('V')
                .long("version")
                .help("Print version")
                .action(ArgAction::Version),
        )
}

fn main() -> ExitCode {
    let mut cmd = build_cli();
    let matches = cmd.get_matches_mut();

    let file_paths: Vec<PathBuf> = matches
        .get_many::<PathBuf>("file_paths")
        .map(|v| v.cloned().collect())
        .unwrap_or_else(|| vec![PathBuf::from(".")]);
    let excludes: Vec<PathBuf> = matches
        .get_many::<PathBuf>("excludes")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();
    let output_format = match matches
        .get_one::<String>("output_format")
        .map(|s| s.as_str())
    {
        Some("json") => OutputFormat::Json,
        _ => OutputFormat::HumanReadable,
    };
    let cfg = Config {
        file_paths,
        no_lambda_arg: matches.get_flag("no_lambda_arg"),
        no_lambda_pattern_names: matches.get_flag("no_lambda_pattern_names"),
        no_underscore: matches.get_flag("no_underscore"),
        warn_used_underscore: matches.get_flag("warn_used_underscore"),
        quiet: matches.get_flag("quiet"),
        edit: matches.get_flag("edit"),
        hidden: matches.get_flag("hidden"),
        fail: matches.get_flag("fail"),
        output_format,
        excludes,
    };

    let excluded_canon: HashSet<PathBuf> = cfg
        .excludes
        .iter()
        .filter_map(|p| std::fs::canonicalize(p).ok())
        .collect();

    let mut success = true;

    for path in &cfg.file_paths {
        match std::fs::metadata(path) {
            Err(e) => {
                if cfg.output_format == OutputFormat::Json {
                    print_json_error(path, &format!("{}", e));
                } else {
                    eprintln!("Error stating file {}: {}", path.display(), e);
                }
            }
            Ok(md) => {
                if md.is_dir() {
                    // WalkDir traversal
                    let hidden = cfg.hidden;
                    let excluded_canon_ref = &excluded_canon;
                    let walker = WalkDir::new(path).into_iter().filter_entry(move |entry| {
                        // hidden check
                        if !hidden {
                            if let Some(name) = entry.path().file_name() {
                                if name.to_string_lossy().starts_with('.') {
                                    // allow root "." whose file_name is None in Path terms;
                                    // WalkDir file_name for "." returns "."? Check depth:
                                    // original allows scanning "." as root. We allow if path == "."
                                    if entry.path() != Path::new(".") {
                                        return false;
                                    }
                                }
                            }
                        }
                        // exclude check via canonicalize
                        if !excluded_canon_ref.is_empty() {
                            if let Ok(canon) = std::fs::canonicalize(entry.path()) {
                                if excluded_canon_ref.contains(&canon) {
                                    return false;
                                }
                            }
                        }
                        true
                    });
                    for entry_res in walker {
                        let entry = match entry_res {
                            Ok(e) => e,
                            Err(err) => {
                                let payload = format!(
                                    "called `Result::unwrap()` on an `Err` value: {:?}",
                                    err
                                );
                                panic_print(
                                    "/rustc/ded5c06cf21d2b93bffd5d884aa6e96934ee4234/library/core/src/ops/function.rs:166:5",
                                    payload,
                                );
                            }
                        };
                        if entry.file_type().is_file() {
                            let p = entry.path();
                            let is_nix = p
                                .extension()
                                .and_then(|e| e.to_str())
                                .map(|e| e.eq_ignore_ascii_case("nix"))
                                .unwrap_or(false);
                            if is_nix {
                                if process_file(p, &cfg) {
                                    success = false;
                                }
                            }
                        }
                    }
                } else {
                    if process_file(path, &cfg) {
                        success = false;
                    }
                }
            }
        }
    }

    if cfg.fail && !success {
        ExitCode::from(1)
    } else {
        ExitCode::from(0)
    }
}

/// Returns true if dead code was found.
fn process_file(path: &Path, cfg: &Config) -> bool {
    let content = match std::fs::read_to_string(path) {
        Err(e) => {
            if cfg.output_format == OutputFormat::Json {
                print_json_error(path, &format!("{}", e));
            } else {
                eprintln!("Error reading file {}: {}", path.display(), e);
            }
            return false;
        }
        Ok(c) => c,
    };
    let parsed = parser::parse(&content);
    if !parsed.errors.is_empty() {
        if cfg.output_format == OutputFormat::Json {
            let report = JsonReport {
                file: path,
                results: parsed
                    .errors
                    .iter()
                    .map(|m| JsonResult {
                        column: None,
                        end_column: None,
                        line: None,
                        message: m.clone(),
                    })
                    .collect(),
            };
            println!("{}", serde_json::to_string(&report).unwrap());
        } else {
            for e in &parsed.errors {
                eprintln!("Error parsing file {}: {}", path.display(), e);
            }
        }
        return false;
    }

    let opts = Options {
        no_lambda_arg: cfg.no_lambda_arg,
        no_lambda_pattern_names: cfg.no_lambda_pattern_names,
        no_underscore: cfg.no_underscore,
        warn_used_underscore: cfg.warn_used_underscore,
    };
    let analyzer = Analyzer::new(&content, &parsed.comments);
    let (bindings, scopes, lets) = analyzer.analyze(&parsed.expr);
    let results = compute_results(&bindings, &scopes, &opts);

    if results.is_empty() {
        return false;
    }

    if !cfg.quiet {
        match cfg.output_format {
            OutputFormat::Json => {
                let report = JsonReport {
                    file: path,
                    results: results
                        .iter()
                        .map(|r| {
