random.seed(99)
names=["a","b","c","x","y","_a","_u","foo","bar","baz"]
def E(d, env):
    opts=["lit"]*2
    if env: opts+=["var"]*4
    if d<3: opts+=["let","lam","pat","set","rec","list","if","with","assert","inheritset","sel","app","str","op"]
    k=random.choice(opts)
    if k=="var": return random.choice(env)
    if k=="lit": return random.choice(["1","true","\"s\"","[ ]","{ }","1.5","./p","<q>","a:b"])
    if k=="let":
        ns=random.sample(names, random.randint(1,3))
        parts=[]
        for n in ns:
            if random.random()<0.2: parts.append(f"inherit ({E(d+1,env)}) {n};")
            else: parts.append(f"{n} = {E(d+1, env+ns)};")
        return f"(let {' '.join(parts)} in {E(d+1, env+ns)})"
    if k=="lam":
        n=random.choice(names); return f"({n}: {E(d+1, env+[n])})"
    if k=="pat":
        ns=random.sample(names, random.randint(1,3))
        ents=[]
        for n in ns: ents.append(f"{n} ? {E(d+1, env+ns)}" if random.random()<0.35 else n)
        at=random.choice(["", "@args", "args@"])
        pat = "{"+", ".join(ents)+("..." if random.random()<0.3 else "")+"}"
        # fix comma before ... if needed: our generator may produce "{a ...}" - instead handle
        pat=pat.replace("..."," , ...") if "..." in pat and ", ..." not in pat else pat
        if at=="@args": pat=pat+"@args"; env2=env+ns+["args"]
        elif at=="args@": pat="args@"+pat; env2=env+ns+["args"]
        else: env2=env+ns
        return f"({pat}: {E(d+1, env2)})"
    if k=="set" or k=="inheritset":
        ns=random.sample(names, random.randint(0,3))
        parts=[]
        for n in ns:
            if random.random()<0.25: parts.append(f"inherit {n};")
            elif random.random()<0.2: parts.append(f"inherit ({E(d+1,env)}) {n};")
            else: parts.append(f"{n} = {E(d+1,env)};")
        return "{ "+" ".join(parts)+" }"
    if k=="rec":
        ns=random.sample(names, random.randint(1,3))
        return "rec { "+" ".join(f"{n} = {E(d+1, env+ns)};" for n in ns)+" }"
    if k=="list": return "[ "+" ".join(E(d+1,env) for _ in range(random.randint(0,3)))+" ]"
